#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("Starting GPIO control loop. Press Ctrl+C to exit.\n");

    while (running) {
        /* Toggle both pins */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1)");
            break;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2)");
            break;
        }
        printf("GPIO 2 and GPIO 3 HIGH\n");
        fflush(stdout);

        sleep(2);

        if (!running) break;

        /* Reset both pins */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1)");
            break;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2)");
            break;
        }
        printf("GPIO 2 and GPIO 3 LOW\n");
        fflush(stdout);

        sleep(2);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

