#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5a
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[3];
    if (read(fd, buf, 3) != 3) {
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", MLX90614_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t raw;
        if (i2c_read_reg16(fd, 0x00, &raw) < 0) {
            fprintf(stderr, "Error reading from MLX90614: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        printf("Raw: 0x%04x\n", raw);
        fflush(stdout);
        sleep(5);
    }

    close(fd);
    return 0;
}

