#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    while (running) {
        uint8_t reg = 0x00;
        uint8_t buf[2];

        if (write(fd, &reg, 1) != 1) {
            perror("write config reg");
            break;
        }

        if (read(fd, buf, 2) != 2) {
            perror("read config reg");
            break;
        }

        uint16_t config = ((uint16_t)buf[0] << 8) | buf[1];
        config = (config & 0x8000) | (0x4000) | (0x0000);

        reg = 0x01;
        if (write(fd, &reg, 1) != 1) {
            perror("write config");
            break;
        }

        if (write(fd, (uint8_t *)&config, 2) != 2) {
            perror("write config");
            break;
        }

        usleep(100000);

        reg = 0x00;
        if (write(fd, &reg, 1) != 1) {
            perror("write config reg");
            break;
        }

        if (read(fd, buf, 2) != 2) {
            perror("read config reg");
            break;
        }

        int16_t raw = ((int16_t)buf[0] << 8) | buf[1];
        float voltage = (float)raw * 4.096 / 32768.0;
        printf("Voltage: %.4f V\n", voltage);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    /* Set both outputs high */
    if (gpiod_line_set_value(line17, 1) < 0) {
        perror("gpiod_line_set_value(17)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line18, 1) < 0) {
        perror("gpiod_line_set_value(18)");
        goto cleanup;
    }

    printf("GPIO 17 and 18 set HIGH\n");
    fflush(stdout);

    /* Sleep for 5 seconds, checking running flag every second */
    for (int i = 0; i < 5 && running; i++) {
        sleep(1);
    }

    /* Set both outputs low */
    if (gpiod_line_set_value(line17, 0) < 0) {
        perror("gpiod_line_set_value(17)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line18, 0) < 0) {
        perror("gpiod_line_set_value(18)");
        goto cleanup;
    }

    printf("GPIO 17 and 18 set LOW\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PERIOD_US 1000000  /* 1 second in microseconds */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure GPIO 18 as output */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 1 kHz */
    if (gpioSetPWMfrequency(PWM_PIN, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 1000000 (duty cycle resolution 0.1%) */
    if (gpioSetPWMrange(PWM_PIN, 1000000) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set initial duty cycle to 0 */
    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set initial PWM duty cycle on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output started on GPIO %d. Frequency: 1 kHz, Range: 1,000,000.\n", PWM_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main loop: cycle duty cycle between 0 and 1,000,000 */
    while (running) {
        if (gpioPWM(PWM_PIN, 0) != 0) {
            fprintf(stderr, "Warning: gpioPWM(0) failed.\n");
        }
        printf("GPIO %d: PWM OFF (duty=%u)\n", PWM_PIN, 0);
        fflush(stdout);

        if (!running) break;

        if (gpioPWM(PWM_PIN, 1000000) != 0) {
            fprintf(stderr, "Warning: gpioPWM(1,000,000) failed.\n");
        }
        printf("GPIO %d: PWM ON (duty=%u)\n", PWM_PIN, 1000000);
        fflush(stdout);

        if (!running) break;

        gpioDelay(PERIOD_US / 2);  /* 0.5 s */
    }

    /* Clean shutdown: set PWM to 0 and release pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM output stopped. pigpio terminated.\n");
    return EXIT_SUCCESS;
}

