static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    struct timespec start, end;
    long long elapsed_us;

    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(2);

    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10);

    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0;
    }

    struct timespec ts_start = {0, 0};
    struct timespec ts_end = {0, 0};
    int timeout = TIMEOUT_US;

    while (gpiod_line_get_value(echo) == 0) {
        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
        timeout--;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_start);

    timeout = TIMEOUT_US;
    while (gpiod_line_get_value(echo) == 1) {
        if (timeout <= 0) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0;
        }
        timeout--;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &ts_end);

    elapsed_us = (ts_end.tv_sec - ts_start.tv_sec) * 1000000LL +
                 (ts_end.tv_nsec - ts_start.tv_nsec) / 1000LL;

    double distance = (elapsed_us / 1000000.0) * 34300.0 / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }

    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Error getting trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error getting echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Error requesting trigger as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Error requesting echo as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance sensor started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance(trig, echo);
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Measurement failed\n");
        }
        sleep(60);
    }

    printf("\nExiting...\n");
    ret = 0;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

/*
 * ADS1115 sampler using Linux I2C dev (no wiringPi).
 *
 * Wiring:
 *   ADS1115 VDD  -> 3.3 V (Pin 1)
 *   ADS1115 GND  -> GND   (Pin 9)
 *   ADS1115 SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   ADS1115 SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *   ADS1115 ADDR -> GND  (address 0x28)
 *
 * Build:  gcc -O2 -Wall -o ads1115_sampler ads1115_sampler.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bits */
#define ADS1115_CFG_OS_BEGIN   (1u << 15)
#define ADS1115_CFG_MUX_AIN0   (0x4000u)   /* AIN0 vs GND */
#define ADS1115_CFG_PGA_4_096 (0x0200u)   /* +/-4.096 V */
#define ADS1115_CFG_MODE_SS   (0x0100u)   /* Single-shot */
#define ADS1115_CFG_DR_128    (0x0080u)   /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE (0x0003u)  /* Disable comparator */

#define SAMPLE_INTERVAL_SEC  5
#define CONV_TIMEOUT_MS      100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit value to an ADS1115 register. */
static int ads1115_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an ADS1115 register. */
static int ads1115_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* Trigger a single-shot conversion on AIN0 and return the raw 16-bit result. */
static int ads1115_read_ain0(int fd, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS_BEGIN
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(fd, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Poll the OS bit until the conversion completes or timeout. */
    for (int i = 0; i < CONV_TIMEOUT_MS; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0)
            return -1;
        if (cfg & ADS1115_CFG_OS_BEGIN)
            break;
        usleep(1000);
    }

    uint16_t raw;
    if (ads1115_read_reg(fd, ADS1115_REG_CONVERSION, &raw) != 0)
        return -1;

    *raw_out = (int16_t)raw;
    return 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify the device is present by reading the config register. */
    uint16_t cfg;
    if (ads1115_read_reg(fd, ADS1115_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "ADS1115 not detected at address 0x%02X.\n",
                ADS1115_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADS1115 detected (config = 0x%04X). Sampling AIN0 every %d s.\n",
           cfg, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_ain0(fd, &raw) != 0) {
            fprintf(stderr, "Read failed; continuing.\n");
        } else {
            printf("AIN0: %d\n", raw);
            fflush(stdout);
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
