#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define NUM_CYCLES 3
#define DELAY_SECONDS 2

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "rpi-digital-out", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting 3 cycles of GPIO %d toggling. Press Ctrl+C to exit early.\n", GPIO_LINE_OFFSET);

    for (int cycle = 0; cycle < NUM_CYCLES && keep_running; cycle++) {
        printf("Cycle %d/%d: ", cycle + 1, NUM_CYCLES);
        fflush(stdout);

        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value HIGH");
            break;
        }
        printf("HIGH\n");
        fflush(stdout);

        sleep(DELAY_SECONDS);
        if (!keep_running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value LOW");
            break;
        }
        printf("LOW\n");
        fflush(stdout);

        sleep(DELAY_SECONDS);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    /*
     * ADS1115 register 0x01: Config register
     * 16-bit: MUX[14:12]=100 (AIN0 vs GND), PGA[11:9]=001 (+/-4.096V),
     * MODE[8]=0 (continuous), DR[7:5]=100 (128 SPS),
     * COMP_MODE[1]=0, COMP_POL[0]=0, COMP_LAT[0]=0, COMP_QUE[4:0]=11 (disable comparator)
     * => 0xC183
     */
    uint8_t config[3] = {
        0xC1,
        0x83,
        0x83  /* Repeat-start byte for 16-bit write */
    };

    if (write(fd, config, sizeof(config)) != (ssize_t)sizeof(config)) {
        perror("write config");
        goto cleanup;
    }

    /*
     * ADS1115 register 0x00: Conversion register
     * Read it back to verify the config write and to sample the ADC value.
     */
    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1) {
        perror("write pointer");
        goto cleanup;
    }

    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        if (n < 0) perror("read");
        else fprintf(stderr, "Short read: %zd bytes\n", n);
        goto cleanup;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    printf("ADS1115 AIN0: %d\n", raw);

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (LOW).\n", GPIO_PIN_1, GPIO_PIN_2);

    /* Main loop: toggle every 5 seconds until interrupted */
    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO values.\n");
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, val1, GPIO_PIN_2, val2);

        /* Toggle both lines */
        if (gpiod_line_set_value(line1, val1 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }

        /* Sleep 5 seconds, checking running flag every second for responsive shutdown */
        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

