#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pin_offsets[NUM_PINS] = {4, 17, 22, 27};
static const char *chip_name = "gpiochip0";

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i;
    int ret;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "rpi-gpio-control", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_offsets[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", pin_offsets[i]);
                goto cleanup;
            }
        }
        printf("Pins: %u=%d, %u=%d, %u=%d, %u=%d\n",
               pin_offsets[0], values[0],
               pin_offsets[1], values[1],
               pin_offsets[2], values[2],
               pin_offsets[3], values[3]);
        fflush(stdout);
        sleep(2);
    }

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 4
#define GPIO_PIN_2 18
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 4)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value low */
    if (gpiod_line_request_output(line1, "rpi-gpio-control", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "rpi-gpio-control", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 18)");
        goto cleanup;
    }

    /* Main loop: drive both pins high, then low, reporting each step */
    while (running) {
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 4 high)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 18 high)");
            goto cleanup;
        }
        printf("GPIO 4 and GPIO 18 set HIGH\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
        if (!running) break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 4 low)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 18 low)");
            goto cleanup;
        }
        printf("GPIO 4 and GPIO 18 set LOW\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines for the two pins */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (line1 == NULL) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (line2 == NULL) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "rpi-digital-out", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "rpi-digital-out", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("Raspberry Pi Digital Output Control (libgpiod)\n");
    printf("Pins: GPIO %d, GPIO %d\n", GPIO_PIN_1, GPIO_PIN_2);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO values (val1=%d, val2=%d)\n", val1, val2);
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, val1, GPIO_PIN_2, val2);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1 != NULL) {
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

