/*
 * si7021_reader.c
 *
 * Reads temperature and humidity from an SI7021 on /dev/i2c-1 at address 0x40.
 * Prints each reading to stdout once every 5 seconds until interrupted.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_reader si7021_reader.c
 * Run:    ./si7021_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define I2C_DEV            "/dev/i2c-1"
#define READ_INTERVAL_SEC  5
#define MAX_RETRIES        3

/* SI7021 commands */
#define CMD_MEASURE_TEMP_HOLD  0xE3
#define CMD_MEASURE_HUMID_HOLD 0xE5
#define CMD_READ_PREV_TEMP    0xE0
#define CMD_READ_PREV_HUMID   0xE2

/* Conversion time (ms) for hold-master mode */
#define CONV_TIME_MS 25

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Write a single command byte to the SI7021.
 * Returns 0 on success, -1 on error.
 */
static int si7021_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the SI7021 into `buf`.
 * Returns 0 on success, -1 on error.
 */
static int si7021_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Trigger a measurement and read the result.
 * Returns 0 on success and fills `out`; -1 on error or invalid data.
 */
static int si7021_measure(int fd, uint8_t cmd, uint16_t *out)
{
    if (si7021_write_cmd(fd, cmd) < 0)
        return -1;

    /* Wait for conversion to complete */
    struct timespec ts = { 0, CONV_TIME_MS * 1000000L };
    nanosleep(&ts, NULL);

    uint8_t buf[2];
    if (si7021_read(fd, buf, sizeof(buf)) < 0)
        return -1;

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read a measurement from the SI7021.
 * Returns 0 on success and fills `out`; -1 on error or invalid data.
 */
static int si7021_read_measurement(int fd, uint16_t *out)
{
    /*
     * Attempt a hold-master measurement first.  If that fails, fall back
     * to reading the previous result (command 0xE0/0xE2) which returns the
     * last conversion performed by the device.
     */
    if (si7021_measure(fd, CMD_MEASURE_TEMP_HOLD, out) < 0) {
        if (si7021_measure(fd, CMD_READ_PREV_TEMP, out) < 0)
            return -1;
        fprintf(stderr, "Warning: previous measurement read (0xE0)\n");
        return 0;
    }
    return 0;
}

/*
 * Validate a temperature reading.  Returns 0 if valid, -1 otherwise.
 */
static int validate_temperature(float temp)
{
    if (temp < -40.0f || temp > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", temp);
        return -1;
    }
    return 0;
}

/*
 * Validate a humidity reading.  Returns 0 if valid, -1 otherwise.
 */
static int validate_humidity(float hum)
{
    if (hum < 0.0f || hum > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f %%\n", hum);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /*
     * Probe: issue a zero-length write to detect device presence.
     * A NACK here usually means the device is not present at this address.
     */
    uint8_t probe;
    if (write(fd, &probe, 0) < 0) {
        fprintf(stderr, "SI7021 at 0x%02X not responding: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SI7021 reader started on %s (addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_DEV, SI7021_ADDR);
    fflush(stdout);

    while (g_running) {
        uint16_t raw_temp, raw_humid;

        if (si7021_read_measurement(fd, &raw_temp) < 0) {
            fprintf(stderr, "Measurement read failed; retrying in %d s...\n",
                    READ_INTERVAL_SEC);
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        float temp = -46.85f + 175.72f * ((float)raw_temp / 65536.0f);
        float hum  = -6.0f  + 125.0f  * ((float)raw_humid / 65536.0f);

        if (validate_temperature(temp) < 0 || validate_humidity(hum) < 0) {
            sleep(READ_INTERVAL_SEC);
            continue;
        }

        printf("Temperature: %.2f C  Humidity: %.2f %%\n", temp, hum);
        fflush(stdout);

        /*
         * Sleep in 1-second increments so SIGINT is noticed promptly.
         */
        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = {reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF)};
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *val = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    uint16_t config = 0x8483; // AIN0 single-ended, 4.096V, 128 SPS, continuous
    if (i2c_write_reg16(fd, CONFIG_REG, config) < 0) {
        perror("write config");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        uint16_t raw;
        if (i2c_read_reg16(fd, CONVERSION_REG, &raw) < 0) {
            perror("read conversion");
            close(fd);
            return 1;
        }

        float voltage = (raw * REF_VOLTAGE) / 32768.0;
        printf("Reading %d: %.4f V\n", i + 1, voltage);
        fflush(stdout);

        if (i < 2) sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 6
static const unsigned int pin_offsets[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t keep_running = 1;

static void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i;
    int ret;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Acquire each line */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }
    }

    /* Request each line as output, initially low */
    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_request_output(lines[i], "gpio-cycle", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_offsets[i]);
            goto cleanup;
        }
    }

    /* Install signal handler for graceful shutdown */
    signal(SIGINT, int_handler);
    signal(SIGTERM, int_handler);

    printf("Starting 256 cycles of GPIO toggling. Press Ctrl+C to exit early.\n");

    while (keep_running) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", pin_offsets[i]);
                goto cleanup;
            }
        }
        printf("Cycle %d: %d %d %d %d %d %d\n",
               (keep_running ? (i + 1) : -1),
               values[0], values[1], values[2], values[3], values[4], values[5]);
        fflush(stdout);

        usleep(10000); /* 10 ms delay between cycles */
    }

    printf("\nExiting cleanly.\n");

cleanup:
    /* Release each line individually */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return (keep_running ? EXIT_FAILURE : EXIT_SUCCESS);
}

#include <stdio.h>
