    if (gpiod_line_request_output(line1, "rpi-digital-out", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "rpi-digital-out", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        goto cleanup;
    }

    printf("Starting GPIO control loop. Press Ctrl+C to exit.\n");

    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO values (val1=%d, val2=%d).\n", val1, val2);
            break;
        }

        printf("GPIO 2: %d, GPIO 3: %d\n", val1, val2);
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

