#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pin_offsets[NUM_PINS] = {8, 9, 10, 11};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i;
    int ret;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as output, initially low */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for offset %u\n", pin_offsets[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "rpi-digital-out", 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for offset %u: %s\n",
                    pin_offsets[i], strerror(-ret));
            goto cleanup;
        }
    }

    /* Main loop: drive each line, report state, sleep 0.1 s */
    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for offset %u: %s\n",
                        pin_offsets[i], strerror(-ret));
                goto cleanup;
            }
        }

        printf("Pins: %u=%d, %u=%d, %u=%d, %u=%d\n",
               pin_offsets[0], values[0],
               pin_offsets[1], values[1],
               pin_offsets[2], values[2],
               pin_offsets[3], values[3]);
        fflush(stdout);

        usleep(100000); /* 0.1 seconds */
    }

cleanup:
    /* Release each line individually (safe even if request failed) */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

