#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_serial(int *fd) {
    *fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SERIAL_PORT, strerror(errno));
        return -1;
    }

    if (fcntl(*fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(*fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(*fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = -1;
    if (init_serial(&fd) != 0) {
        return EXIT_FAILURE;
    }

    printf("Serial port initialized on %s at 9600 baud.\n", SERIAL_PORT);

    char buffer[256];
    size_t total = 0;
    ssize_t bytes_read;

    while (g_running) {
        bytes_read = read(fd, buffer + total, sizeof(buffer) - 1 - total);

        if (bytes_read < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
            break;
        }

        if (bytes_read == 0) {
            fprintf(stderr, "Serial port closed by peer.\n");
            break;
        }

        total += (size_t)bytes_read;
        buffer[total] = '\0';

        printf("Received: %s\n", buffer);
        fflush(stdout);
    }

    if (fd >= 0) {
        close(fd);
    }

    printf("Serial port closed.\n");
    return EXIT_SUCCESS;
}

