    for (int i = 0; i < NUM_PINS && running; i++) {
        if (gpiod_line_set_value(lines[i], 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %u high\n", pin_offsets[i]);
            goto cleanup;
        }
        values[i] = 1;
        printf("GPIO %u set HIGH\n", pin_offsets[i]);
        fflush(stdout);
        usleep(100000); /* 100 ms */

        if (gpiod_line_set_value(lines[i], 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %u low\n", pin_offsets[i]);
            goto cleanup;
        }
        values[i] = 0;
        printf("GPIO %u set LOW\n", pin_offsets[i]);
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually (safe even if request failed) */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

