#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define NUM_PINS 2

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;
    int i;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = -1;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the lines */
    lines[0] = gpiod_chip_get_line(chip, GPIO_17);
    if (!lines[0]) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    lines[1] = gpiod_chip_get_line(chip, GPIO_18);
    if (!lines[1]) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value low */
    if (gpiod_line_request_output(lines[0], "rpi-digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(lines[1], "rpi-digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Read initial states */
    values[0] = gpiod_line_get_value(lines[0]);
    if (values[0] < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    values[1] = gpiod_line_get_value(lines[1]);
    if (values[1] < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    printf("Initial state: GPIO %d = %d, GPIO %d = %d\n",
           GPIO_17, values[0], GPIO_18, values[1]);
    fflush(stdout);

    /* Main loop: set one pin high, read the other, validate */
    while (running) {
        /* Set GPIO 17 high */
        if (gpiod_line_set_value(lines[0], 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_17, strerror(errno));
            goto cleanup;
        }

        /* Small delay to let the output stabilize */
        usleep(10000); /* 10 ms */

        /* Read GPIO 18 */
        int val = gpiod_line_get_value(lines[1]);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_18, strerror(errno));
            goto cleanup;
        }

        /* Validity check: 0 or 1 only */
        if (val != 0 && val != 1) {
            fprintf(stderr, "Invalid reading %d from GPIO %d\n", val, GPIO_18);
            goto cleanup;
        }

        printf("GPIO %d = %d, GPIO %d = %d\n",
               GPIO_17, 1, GPIO_18, val);
        fflush(stdout);

        /* Toggle GPIO 17 */
        if (gpiod_line_set_value(lines[0], 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_17, strerror(errno));
            goto cleanup;
        }

        /* Small delay before next iteration */
        usleep(100000); /* 100 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and chip */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nClean shutdown complete.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_RETRIES 5
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static int wait_level(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (running) {
        int v = gpiod_line_get_value(line);
        if (v < 0) return -1;
        if (v == level) return 0;
        sleep_us(10);
        elapsed += 10;
        if (elapsed >= timeout_us) return -2;
    }
    return -3;
}

static int read_dht11(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    for (i = 0; i < MAX_RETRIES; i++) {
        memset(data, 0, sizeof(data));

        if (gpiod_line_request_output(line, "dht11", 1) < 0) {
            fprintf(stderr, "request_output failed: %s\n", strerror(errno));
            return -1;
        }
        gpiod_line_set_value(line, 1);
        sleep_us(50);
        gpiod_line_set_value(line, 0);
        sleep_us(20);
        gpiod_line_set_value(line, 1);
        sleep_us(40);

        if (gpiod_line_request_input(line, "dht11") < 0) {
            fprintf(stderr, "request_input failed: %s\n", strerror(errno));
            return -1;
        }

        if (wait_level(line, 0, 100) < 0) {
            fprintf(stderr, "Timeout waiting for low\n");
            continue;
        }
        if (wait_level(line, 1, 100) < 0) {
            fprintf(stderr, "Timeout waiting for high\n");
            continue;
        }

        for (int j = 0; j < 40; j++) {
            if (wait_level(line, 0, 100) < 0) {
                fprintf(stderr, "Timeout waiting for data low\n");
                goto retry;
            }
            uint32_t start = gpiod_line_get_value(line);
            if (start < 0) {
                fprintf(stderr, "Error reading line during data\n");
                goto retry;
            }
            if (start & 1) {
                data[j / 8] |= (1 << (7 - (j % 8)));
            }
            if (wait_level(line, 1, 100) < 0) {
                fprintf(stderr, "Timeout waiting for data high\n");
                goto retry;
            }
        }

        if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
            fprintf(stderr, "Checksum error\n");
            goto retry;
        }

        uint16_t raw_h = (data[0] << 8) | data[1];
        uint16_t raw_t = (data[2] << 8) | data[3];
        *hum = raw_h / 10.0f;
        if (raw_t & 0x8000) {
            *temp = -(raw_t & 0x7FFF) / 10.0f;
        } else {
            *temp = raw_t / 10.0f;
        }
        return 0;

    retry:
        sleep_us(2000);
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", DHT11_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp = 0.0f, hum = 0.0f;
    int rc = read_dht11(line, &temp, &hum);

    if (rc == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
    } else {
        fprintf(stderr, "Failed to read DHT11 after %d retries\n", MAX_RETRIES);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return (rc == 0) ? 0 : 1;
}

