#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define NUM_CYCLES 3
#define DELAY_SECONDS 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "rpi_control", 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "rpi_control", 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    printf("Starting 3 cycles of GPIO control. Press Ctrl+C to exit.\n");

    for (int cycle = 0; cycle < NUM_CYCLES && program_running; cycle++) {
        printf("\n--- Cycle %d ---\n", cycle + 1);

        /* Set both pins high */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value(line1, high)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(line2, high)");
            goto cleanup;
        }
        printf("GPIO 2 and GPIO 3 set HIGH\n");
        sleep(DELAY_SECONDS);

        if (!program_running) break;

        /* Set both pins low */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value(line1, low)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(line2, low)");
            goto cleanup;
        }
        printf("GPIO 2 and GPIO 3 set LOW\n");
        sleep(DELAY_SECONDS);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Program finished.\n");
    return ret;
}

