#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 5
static const unsigned int pin_offsets[NUM_PINS] = {4, 17, 18, 22, 27};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }

        ret = gpiod_line_request_output(lines[i], "rpi-gpio-control", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_offsets[i]);
            goto cleanup;
        }
    }

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        goto cleanup;
    }

    printf("Raspberry Pi GPIO control started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", pin_offsets[i]);
                goto cleanup;
            }
        }
        printf("Pins: %u=%d, %u=%d, %u=%d, %u=%d, %u=%d\n",
               pin_offsets[0], values[0],
               pin_offsets[1], values[1],
               pin_offsets[2], values[2],
               pin_offsets[3], values[3],
               pin_offsets[4], values[4]);
        fflush(stdout);

        usleep(50000); /* 0.05 seconds */
    }

    printf("\nExiting...\n");

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

