#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* Ensure clean shutdown on normal exit paths */
    atexit((void (*)(void))gpioTerminate);

    /* Install signal handler for graceful Ctrl+C exit */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Configure PWM pins as outputs */
    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PWM pin mode\n");
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 1 kHz (1000 Hz) */
    if (gpioSetPWMfrequency(PWM_PIN_1, 1000) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, 1000) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, 1000) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 for 8-bit resolution */
    if (gpioSetPWMrange(PWM_PIN_1, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, 255) != 0) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        return EXIT_FAILURE;
    }

    /* Main loop: drive PWM on and off in a repeating pattern */
    while (running) {
        /* PWM duty cycle 0-255 */
        if (gpioPWM(PWM_PIN_1, 0) != 0 ||
            gpioPWM(PWM_PIN_2, 128) != 0 ||
            gpioPWM(PWM_PIN_3, 255) != 0) {
            fprintf(stderr, "Error: gpioPWM failed\n");
            return EXIT_FAILURE;
        }
        printf("PWM1=%3d  PWM2=%3d  PWM3=%3d\n", 0, 128, 255);
        fflush(stdout);
        gpioDelay(100000); /* 0.15 s in microseconds */

        if (!running) break;

        if (gpioPWM(PWM_PIN_1, 255) != 0 ||
            gpioPWM(PWM_PIN_2, 0) != 0 ||
            gpioPWM(PWM_PIN_3, 0) != 0) {
            fprintf(stderr, "Error: gpioPWM failed\n");
            return EXIT_FAILURE;
        }
        printf("PWM1=%3d  PWM2=%3d  PWM3=%3d\n", 255, 0, 0);
        fflush(stdout);
        gpioDelay(100000);
    }

    /* Turn off all PWM outputs before exit */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);

    return EXIT_SUCCESS;
}

#include <stdio.h>
