#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define OPT3001_ADDR 0x44
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_DEV);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1) {
        perror("write reg");
        goto cleanup;
    }

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0) perror("read");
        else fprintf(stderr, "Short read: %zd bytes\n", n);
        goto cleanup;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    float voltage = (float)raw * 0.00390625f;
    printf("Voltage: %.4f V\n", voltage);

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

