#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 2)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "rpi-dual-out", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "rpi-dual-out", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 3)");
        goto cleanup;
    }

    /* Read initial states */
    int v1 = gpiod_line_get_value(line1);
    int v2 = gpiod_line_get_value(line2);
    if (v1 < 0 || v2 < 0) {
        fprintf(stderr, "Initial read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Initial state: GPIO 2 = %d, GPIO 3 = %d\n", v1, v2);
    fflush(stdout);

    /* Set both high, then both low, then validate */
    if (gpiod_line_set_value(line1, 1) < 0 || gpiod_line_set_value(line2, 1) < 0) {
        perror("gpiod_line_set_value (high)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line1, 0) < 0 || gpiod_line_set_value(line2, 0) < 0) {
        perror("gpiod_line_set_value (low)");
        goto cleanup;
    }

    /* Validate: both should be low */
    v1 = gpiod_line_get_value(line1);
    v2 = gpiod_line_get_value(line2);
    if (v1 < 0 || v2 < 0) {
        fprintf(stderr, "Validation read failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (v1 != 0 || v2 != 0) {
        fprintf(stderr, "Validation failed: GPIO 2 = %d, GPIO 3 = %d\n", v1, v2);
        goto cleanup;
    }

    printf("GPIO 2 and GPIO 3 are functioning correctly.\n");
    fflush(stdout);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

