#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_BUF_SIZE 256

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int init_serial(int *fd) {
    *fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SERIAL_PORT, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(*fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;

    if (tcsetattr(*fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static void cleanup_serial(int fd) {
    if (fd >= 0) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction failed: %s\n", strerror(errno));
    }

    int serial_fd = -1;
    if (init_serial(&serial_fd) != 0) {
        return EXIT_FAILURE;
    }

    printf("Serial port initialized on %s at 9600 baud.\n", SERIAL_PORT);
    printf("Reading data from the device...\n");

    char read_buf[READ_BUF_SIZE];
    size_t total_read = 0;
    int no_data_count = 0;

    while (!g_stop) {
        ssize_t bytes_read = read(serial_fd, read_buf + total_read, READ_BUF_SIZE - 1 - total_read);

        if (bytes_read > 0) {
            total_read += (size_t)bytes_read;
            read_buf[total_read] = '\0';
            printf("Received: %s", read_buf);
            fflush(stdout);
            no_data_count = 0;
        } else if (bytes_read == 0) {
            no_data_count++;
            if (no_data_count > 10) {
                fprintf(stderr, "Warning: No data received from device.\n");
                no_data_count = 0;
            }
        } else {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                no_data_count++;
                if (no_data_count > 10) {
                    fprintf(stderr, "Warning: No data received from device.\n");
                    no_data_count = 0;
                }
            } else {
                fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
                break;
            }
        }

        usleep(10000);
    }

    printf("\nExiting program.\n");
    cleanup_serial(serial_fd);
    return EXIT_SUCCESS;
}

