#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int duty = 0; duty <= 255 && running; duty++) {
            int vals[3] = {duty, duty, duty};
            if (gpioPWM(PWM_PIN_1, vals[0]) != 0 ||
                gpioPWM(PWM_PIN_2, vals[1]) != 0 ||
                gpioPWM(PWM_PIN_3, vals[2]) != 0) {
                fprintf(stderr, "Error: PWM write failed at duty %d\n", duty);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty: %3d  (pin1=%3d, pin2=%3d, pin3=%3d)\n",
                   duty, vals[0], vals[1], vals[2]);
            fflush(stdout);
            gpioDelay(100000); /* 100 ms */
        }
        for (int duty = 255; duty >= 0 && running; duty--) {
            int vals[3] = {duty, duty, duty};
            if (gpioPWM(PWM_PIN_1, vals[0]) != 0 ||
                gpioPWM(PWM_PIN_2, vals[1]) != 0 ||
                gpioPWM(PWM_PIN_3, vals[2]) != 0) {
                fprintf(stderr, "Error: PWM write failed at duty %d\n", duty);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty: %3d  (pin1=%3d, pin2=%3d, pin3=%3d)\n",
                   duty, vals[0], vals[1], vals[2]);
            fflush(stdout);
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define NUM_SENSORS 3
static const char *sensor_paths[NUM_SENSORS] = {
    "/sys/bus/w1/devices/28-0000053b30f2",
    "/sys/bus/w1/devices/28-0000053b30f3",
    "/sys/bus/w1/devices/28-0000053b30f4"
};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *path, float *temperature) {
    FILE *fp;
    char line[256];
    int i;

    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "Temperature read failed (CRC check): %s\n", line);
        return -1;
    }

    char *temp_str = strstr(line, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1;
    }

    errno = 0;
    char *endptr = NULL;
    long temp_raw = strtol(temp_str + 2, &endptr, 10);
    if (errno != 0 || endptr == temp_str + 2) {
        fprintf(stderr, "Error parsing temperature from %s\n", path);
        return -1;
    }

    *temperature = (float)temp_raw / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    while (running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            float temperature;
            if (read_temperature(sensor_paths[i], &temperature) == 0) {
                printf("Sensor %d: %.2f C\n", i + 1, temperature);
            } else {
                fprintf(stderr, "Failed to read temperature from sensor %d\n", i + 1);
            }
        }
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define MEASURE_CMD 0xE3
#define CONV_DELAY_US 10000
#define LOOP_DELAY_S 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint8_t cmd = MEASURE_CMD;
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    usleep(CONV_DELAY_US);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    float t = (175.72f * raw / 65536.0f) - 46.85f;
    if (t < -40.0f || t > 125.0f) {
        fprintf(stderr, "Temperature out of valid range: %.2f\n", t);
        return -1;
    }
    *temp = t;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        float temp;
        if (read_temperature(fd, &temp) == 0) {
            printf("Temperature: %.2f C\n", temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }
        for (int i = 0; i < LOOP_DELAY_S && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

