#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    // Enable measurement mode
    uint8_t pwr_ctl = 0x08; // bit 3 = measure
    if (write(fd, &pwr_ctl, 1) != 1) {
        perror("write power control");
        goto cleanup;
    }

    while (running) {
        uint8_t data[6];
        ssize_t bytes = read(fd, data, 6);
        if (bytes != 6) {
            if (bytes < 0) perror("read");
            else fprintf(stderr, "Short read: %zd bytes\n", bytes);
            break;
        }

        // ADXL345 outputs little-endian two's complement
        int16_t x = (int16_t)((data[1] << 8) | data[0]);
        int16_t y = (int16_t)((data[3] << 8) | data[2]);
        int16_t z = (int16_t)((data[5] << 8) | data[4]);

        printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        usleep(100000); // 0.1 seconds
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        // Put back into standby mode
        uint8_t pwr_ctl_off = 0x00;
        write(fd, &pwr_ctl_off, 1);
        close(fd);
    }
    return ret;
}

