#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pins[NUM_PINS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit = 0, byte = 0;
    int last = 1;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    usleep(1000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    for (int i = 0; i < 85 && running; i++) {
        int t = gpiod_line_get_value(line);
        if (t < 0) return -1;
        if (t != last) {
            if (i > 1 && i % 2 == 0) {
                data[byte] <<= 1;
                if (t == 0) data[byte] |= 1;
                bit++;
                if (bit == 8) byte++;
            }
            last = t;
        }
        usleep(50);
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) *temp = -*temp;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            struct gpiod_line *line = gpiod_chip_get_line(chip, pins[i]);
            if (!line) {
                fprintf(stderr, "Failed to get GPIO %u\n", pins[i]);
                continue;
            }
            float t, h;
            if (read_dht22(line, &t, &h) == 0) {
                printf("GPIO %u: Temp = %.1f C, Hum = %.1f %%\n", pins[i], t, h);
            } else {
                fprintf(stderr, "GPIO %u: Read failed\n", pins[i]);
            }
            gpiod_line_release(line);
        }
        sleep(2);
    }

    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define STEP_DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int values[] = {0, 0, 0};
    int pins_set[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};

    while (running) {
        for (size_t i = 0; i < sizeof(values) / sizeof(values[0]); i++) {
            values[i] = (values[i] + 1) % PWM_RANGE;
            if (gpioPWM(pins_set[i], values[i]) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on GPIO %d.\n", pins_set[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM: GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               PWM_PIN_1, values[0],
               PWM_PIN_2, values[1],
               PWM_PIN_3, values[2]);
        fflush(stdout);

        usleep(STEP_DELAY_US);
    }

    for (size_t i = 0; i < sizeof(values) / sizeof(values[0]); i++) {
        gpioPWM(pins_set[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

