        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", gpioInitialise());
        return EXIT_FAILURE;
    }

    /* Configure PWM pin as output */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 50 kHz (divisor 1000 for 1 MHz clock) */
    if (gpioSetPWMfrequency(PWM_PIN, 50000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d, 50000) failed.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 for 8-bit resolution */
    if (gpioSetPWMrange(PWM_PIN, 255) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, 255) failed.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set initial duty cycle to 0 */
    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioPWM(%d, 0) failed.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM output started on GPIO %d. Frequency: 50 kHz, Range: 255.\n", PWM_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop: drive PWM duty cycle in a repeating pattern */
    while (running) {
        if (gpioPWM(PWM_PIN, 128) != 0) {
            fprintf(stderr, "Warning: gpioPWM(%d, 128) failed.\n", PWM_PIN);
            break;
        }
        printf("Duty cycle: 128/255 (%.2f%%)\n", 128.0 / 255.0 * 100.0);
        fflush(stdout);
        gpioDelay(PERIOD_US);

        if (!running) break;

        if (gpioPWM(PWM_PIN, 0) != 0) {
            fprintf(stderr, "Warning: gpioPWM(%d, 0) failed.\n", PWM_PIN);
            break;
        }
        printf("Duty cycle: 0/255 (0%%)\n");
        fflush(stdout);
        gpioDelay(PERIOD_US);
    }

    /* Clean shutdown: ensure PWM is off and release pigpio resources */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("\nPWM output stopped. pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pin_offsets[NUM_PINS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS] = {0, 0, 0, 0};
    int i;
    int ret;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Acquire each line and configure as output, initially low */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for offset %u\n",
                    pin_offsets[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "rpi-digital-out", 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for offset %u\n",
                    pin_offsets[i]);
            goto cleanup;
        }
    }

    /* Main loop: toggle each pin in turn, report state */
    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for offset %u\n",
                        pin_offsets[i]);
                goto cleanup;
            }
            printf("GPIO %u: %s\n", pin_offsets[i],
                   values[i] ? "HIGH" : "LOW");
        }
        printf("---\n");
        fflush(stdout);
        usleep(200000); /* 0.2 seconds */
    }

cleanup:
    /* Release each line individually (safe even if request failed) */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29

#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing command for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing command for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading 2 bytes from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[1] << 8 | buf[0];
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_byte(fd, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x44 && id != 0x4D) {
        fprintf(stderr, "Error: Invalid TCS34725 ID: 0x%02X\n", id);
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) {
        return -1;
    }
    usleep(3000);

    if (i2c_write_byte(fd, TCS34725_ATIME, 0xFF) < 0) {
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x03) < 0) {
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        return -1;
    }

    return 0;
}

static void cleanup(int fd) {
    if (fd >= 0) {
        i2c_write_byte(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        cleanup(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725 sensor.\n");
        cleanup(fd);
        return 1;
    }

    printf("TCS34725 initialized. Reading data every 0.2 seconds. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t clear, red, green, blue;

        if (i2c_read_word(fd, TCS34725_CDATA, &clear) < 0 ||
            i2c_read_word(fd, TCS34725_RDATA, &red) < 0 ||
            i2c_read_word(fd, TCS34725_GDATA, &green) < 0 ||
            i2c_read_word(fd, TCS34725_BDATA, &blue) < 0) {
            fprintf(stderr, "Error reading color data. Retrying...\n");
            usleep(200000);
            continue;
        }

        printf("C: %u, R: %u, G: %u, B: %u\n", clear, red, green, blue);
        usleep(200000);
    }

    printf("\nExiting...\n");
    cleanup(fd);
    return 0;
}

