    if (ssd1306_send_command(fd, 0xA1) < 0) return -1;
    if (ssd1306_send_command(fd, 0xC8) < 0) return -1;
    if (ssd1306_send_command(fd, 0xDA) < 0) return -1;
    if (ssd1306_send_command(fd, 0x12) < 0) return -1;
    if (ssd1306_send_command(fd, 0x81) < 0) return -1;
    if (ssd1306_send_command(fd, 0xCF) < 0) return -1;
    if (ssd1306_send_command(fd, 0xD9) < 0) return -1;
    if (ssd1306_send_command(fd, 0xF1) < 0) return -1;
    if (ssd1306_send_command(fd, 0xDB) < 0) return -1;
    if (ssd1306_send_command(fd, 0x40) < 0) return -1;
    if (ssd1306_send_command(fd, 0xA4) < 0) return -1;
    if (ssd1306_send_command(fd, 0xA6) < 0) return -1;
    if (ssd1306_send_command(fd, 0xAF) < 0) return -1;
    return 0;
}

static int ssd1306_clear(int fd) {
    unsigned char zero = 0x00;
    for (int i = 0; i < SSD1306_WIDTH * SSD1306_HEIGHT / 8; i++) {
        if (ssd1306_send_data(fd, &zero, 1) < 0) return -1;
    }
    return 0;
}

static int ssd1306_display_text(int fd, int x, int y, const char *text) {
    if (ssd1306_send_command(fd, 0xB0 + (y / 8)) < 0) return -1;
    if (ssd1306_send_command(fd, 0x00 + (x & 0x0F)) < 0) return -1;
    if (ssd1306_send_command(fd, 0x10 + ((x >> 4) & 0x0F)) < 0) return -1;
    unsigned char buf[256];
    int len = strlen(text);
    if (len > 255) len = 255;
    for (int i = 0; i < len; i++) {
        buf[i] = (unsigned char)text[i];
    }
    for (int i = len; i < 256; i++) {
        buf[i] = 0x00;
    }
    if (ssd1306_send_data(fd, buf, 256) < 0) return -1;
    return 0;
}

int main() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(fd);
        return 1;
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear failed\n");
        close(fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (ssd1306_display_text(fd, 0, 0, "Hello, World!") < 0) {
            fprintf(stderr, "Failed to display text\n");
            break;
        }
        usleep(100000);
    }

    ssd1306_clear(fd);
    ssd1306_send_command(fd, 0xAE);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 3
static const unsigned int pin_offsets[NUM_PINS] = {2, 3, 5};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = -1;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line and configure as output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "rpi-digital-out", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_offsets[i]);
            goto cleanup;
        }
        values[i] = 0;
    }

    printf("GPIO lines initialized: %u, %u, %u (BCM).\n",
           pin_offsets[0], pin_offsets[1], pin_offsets[2]);
    fflush(stdout);

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
        }
        printf("State: %u %u %u\n", values[0], values[1], values[2]);
        fflush(stdout);

        /* Sleep 5 seconds, but wake early on signal */
        for (int s = 0; s < 5 && running; s++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            if (gpioWrite(pins[i], 1) != 0) {
                fprintf(stderr, "Warning: failed to write GPIO %d\n", pins[i]);
            }
            printf("GPIO %d HIGH\n", pins[i]);
            fflush(stdout);
        }
        sleep(1);

        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            if (gpioWrite(pins[i], 0) != 0) {
                fprintf(stderr, "Warning: failed to write GPIO %d\n", pins[i]);
            }
            printf("GPIO %d LOW\n", pins[i]);
            fflush(stdout);
        }
        sleep(1);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 23
#define ECHO_PIN_ALT 24

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long measure_pulse(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    struct timespec t0, t1;
    long long elapsed_us = 0;

    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t0);
        if (elapsed_us > 1000000) return -1;
        usleep(1);
        elapsed_us = (t0.tv_sec - t1.tv_sec) * 1000000LL + (t0.tv_nsec - t1.tv_nsec) / 1000LL;
    }

    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t1);
        if (elapsed_us > 1000000) return -1;
        usleep(1);
        elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000LL + (t1.tv_nsec - t0.tv_nsec) / 1000LL;
    }

    return elapsed_us;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *echo_alt = gpiod_chip_get_line(chip, ECHO_PIN_ALT);
    if (!trig || !echo || !echo_alt) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_alt, "hc-sr04-echo-alt") < 0) {
        perror("gpiod_line_request_input echo_alt");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_line_release(echo_alt);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        long long duration = measure_pulse(trig, echo);
        if (duration < 0) {
            fprintf(stderr, "Error: Timeout waiting for echo pulse.\n");
            break;
        }

        long long distance = duration / 58.0;
        printf("Distance: %.2f cm\n", distance);

        usleep(200000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(echo_alt);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PIXELS 1
#define STRIP_PIN 18
#define DELAY_US 10000  /* 0.01 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Ensure strip pin is in a known state before use */
    gpioSetMode(STRIP_PIN, PI_OUTPUT);
    gpioWrite(STRIP_PIN, 0);

    int colours[NUM_PIXELS];
    for (int i = 0; i < NUM_PIXELS; i++) {
        colours[i] = (i % 2 == 0) ? 0 : 255;
    }

    while (running) {
        for (int i = 0; i < NUM_PIXELS; i++) {
            gpioWrite(STRIP_PIN, colours[i]);
        }
        gpioDelay(DELAY_US);
    }

    /* Clean shutdown: turn off all LEDs and release pigpio */
    gpioWrite(STRIP_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

