#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define NUM_IMAGES 10
#define CAPTURE_INTERVAL_SEC 0.05

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

struct buffer {
    void   *start;
    size_t  length;
};

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct buffer *buffers = NULL;
    unsigned int n_buffers = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("Cannot open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: /dev/video0 does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: /dev/video0 does not support streaming I/O\n");
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 2) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        goto cleanup;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("calloc");
        goto cleanup;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }
        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers].start == MAP_FAILED) {
            perror("mmap");
            buffers[n_buffers].start = NULL;
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers && running; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    for (int i = 0; i < NUM_IMAGES && running; ++i) {
        fd_set fds;
        struct timeval tv;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        tv.tv_sec = (time_t)(CAPTURE_INTERVAL_SEC);
        tv.tv_usec = (suseconds_t)((CAPTURE_INTERVAL_SEC - tv.tv_sec) * 1000000);

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            perror("select");
            break;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("VIDIOC_DQBUF");
            break;
        }

        FILE *fp = fopen("image.jpg", "wb");
        if (!fp) {
            perror("fopen");
            break;
        }
        if (fwrite(buffers[buf.index].start, 1, buf.bytesused, fp) != buf.bytesused) {
            perror("fwrite");
            fclose(fp);
            break;
        }
        fclose(fp);

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
    }
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }
    if (fd != -1) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

#define BME280_CHIP_ID 0x60
#define BME280_RESET_CMD 0xB6

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        fprintf(stderr, "Error resetting BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t status;
    int retries = 10;
    do {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status) < 0) {
            fprintf(stderr, "Error reading status: %s\n", strerror(errno));
            return -1;
        }
        if (--retries == 0) {
            fprintf(stderr, "BME280 not ready after reset\n");
            return -1;
        }
        usleep(2000);
    } while (status & 0x01);

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read(int fd, float *temp, float *hum, float *press) {
    uint8_t data[8];
    if (i2c_read_burst(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_p = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_h = (data[6] << 8) | data[7];

    *press = (float)raw_p / 100.0f;
    *temp = (float)raw_t / 100.0f;
    *hum = (float)raw_h / 1000.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("BME280 initialized. Reading every 5 seconds...\n");

    while (running) {
        float temp, hum, press;
        if (bme280_read(fd, &temp, &hum, &press) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%, Pressure: %.2f Pa\n", temp, hum, press);
        } else {
            fprintf(stderr, "Read failed, continuing...\n");
        }
        sleep(5);
    }

    printf("\nExiting...\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0, +/-4.096V, 128 SPS, continuous */
#define ADS1115_CONFIG_BASE 0x8000  /* OS bit: start single conversion */
#define ADS1115_CONFIG_MUX  0x4000  /* AIN0 vs GND */
#define ADS1115_CONFIG_PGA  0x0200  /* +/-4.096V */
#define ADS1115_CONFIG_DR   0x0080  /* 128 SPS */

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify device presence by reading the config register */
    uint16_t cfg_check = 0;
    if (i2c_read16(fd, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding at address 0x%02X\n", ADS1115_ADDR);
        goto cleanup;
    }

    /* Start a single conversion on AIN0 */
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX | ADS1115_CONFIG_PGA | ADS1115_CONFIG_DR;
    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
        goto cleanup;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    while (running) {
        uint16_t raw = 0;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            goto cleanup;
        }

        int16_t value = (int16_t)raw;
        printf("AIN0: %d\n", value);
        fflush(stdout);

        /* Start next conversion */
        config |= ADS1115_CONFIG_BASE;
        if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
            goto cleanup;
        }

        usleep(200000); /* 0.2 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define BCM_PIN 4
#define CONSUMER "rpi-blink"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, BCM_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value(1)");
            goto cleanup;
        }
        printf("GPIO %d HIGH\n", BCM_PIN);
        fflush(stdout);

        if (!running) break;
        sleep(60);

        if (!running) break;
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value(0)");
            goto cleanup;
        }
        printf("GPIO %d LOW\n", BCM_PIN);
        fflush(stdout);

        if (!running) break;
        sleep(60);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 not detected at address 0x%02X.\n", MPU6050_ADDR);
        goto cleanup;
    }

    while (running) {
        uint8_t buf[6];
        if (i2c_read_bytes(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
            break;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
