#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define HD44780_ADDR 0x27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int hd44780_send_byte(int fd, unsigned char byte, unsigned char mode) {
    unsigned char data[2] = {byte & 0xF0, (byte << 4) & 0xF0};
    unsigned char cmd = 0x0C | (mode & 0x01);
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    if (i2c_write_byte(fd, data[0]) < 0) return -1;
    if (i2c_write_byte(fd, data[1]) < 0) return -1;
    return 0;
}

static int hd44780_command(int fd, unsigned char cmd) {
    return hd44780_send_byte(fd, cmd, 0);
}

static int hd44780_data(int fd, unsigned char data) {
    return hd44780_send_byte(fd, data, 1);
}

static int hd44780_init(int fd) {
    usleep(50000);
    if (hd44780_command(fd, 0x30) < 0) return -1;
    usleep(5000);
    if (hd44780_command(fd, 0x30) < 0) return -1;
    usleep(150);
    if (hd44780_command(fd, 0x20) < 0) return -1;
    if (hd44780_command(fd, 0x28) < 0) return -1;
    if (hd44780_command(fd, 0x08) < 0) return -1;
    if (hd44780_command(fd, 0x01) < 0) return -1;
    usleep(2000);
    if (hd44780_command(fd, 0x06) < 0) return -1;
    if (hd44780_command(fd, 0x0C) < 0) return -1;
    return 0;
}

static int hd44780_clear(int fd) {
    return hd44780_command(fd, 0x01);
}

static int hd44780_set_cursor(int fd, int row, int col) {
    int addr = (row == 0) ? 0x80 : 0xC0;
    addr += col;
    return hd44780_command(fd, addr);
}

static int hd44780_write_string(int fd, const char *str) {
    while (*str) {
        if (hd44780_data(fd, (unsigned char)*str) < 0) return -1;
        str++;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        goto cleanup;
    }

    if (hd44780_init(fd) < 0) {
        fprintf(stderr, "HD44780 initialization failed\n");
        goto cleanup;
    }

    while (running) {
        if (hd44780_clear(fd) < 0) break;
        if (hd44780_set_cursor(fd, 0, 0) < 0) break;
        if (hd44780_write_string(fd, "Raspberry Pi") < 0) break;

        if (hd44780_set_cursor(fd, 1, 0) < 0) break;
        if (hd44780_write_string(fd, "Linux I2C Dev") < 0) break;

        sleep(10);
    }

    ret = 0;

cleanup:
    if (fd >= 0) {
        hd44780_clear(fd);
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define WHO_AM_I 0x75
#define WHO_AM_I_VAL 0x68

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    uint8_t whoami = 0;
    if (i2c_read_burst(fd, WHO_AM_I, &whoami, 1) < 0) {
        fprintf(stderr, "Error: MPU6050 not responding (WHO_AM_I read failed).\n");
        goto cleanup;
    }
    if (whoami != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X).\n", whoami, WHO_AM_I_VAL);
        goto cleanup;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to wake MPU6050.\n");
        goto cleanup;
    }
    usleep(100000);

    printf("MPU6050 initialized. Reading 100 samples...\n");
    for (int i = 0; i < 100 && running; i++) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Error: I2C read failed (sample %d).\n", i);
            goto cleanup;
        }
        int16_t ax = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t ay = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t az = (int16_t)((buf[4] << 8) | buf[5]);
        printf("Sample %d: Accel X=%d Y=%d Z=%d\n", i, ax, ay, az);
    }

    ret = 0;

cleanup:
    if (fd >= 0) close(fd);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_14 14
#define GPIO_15 15
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (!line14) {
        perror("gpiod_chip_get_line(GPIO_14)");
        goto cleanup;
    }
    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line15) {
        perror("gpiod_chip_get_line(GPIO_15)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line14, "rpi-gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_14)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line15, "rpi-gpio-control", 0) < 0) {
        perror("gpiod_line_request_output(GPIO_15)");
        goto cleanup;
    }

    printf("GPIO 14 and 15 initialized as outputs (initial state LOW).\n");
    fflush(stdout);

    while (running) {
        int val14 = gpiod_line_get_value(line14);
        int val15 = gpiod_line_get_value(line15);

        if (val14 < 0 || val15 < 0) {
            fprintf(stderr, "Error reading GPIO values: %s\n", strerror(errno));
            /* Brief pause before retry to avoid log flooding */
            sleep(1);
            continue;
        }

        printf("GPIO 14: %d, GPIO 15: %d\n", val14, val15);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line14) {
        gpiod_line_release(line14);
    }
    if (line15) {
        gpiod_line_release(line15);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/reading"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define SENSOR_PIN 4
#define POLL_DELAY_US 10000
#define MAX_RETRIES 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d\n", SENSOR_PIN);
        return -1;
    }
    return value;
}

static int validate_sensor_data(int sensor_value) {
    /* Basic sanity check: ensure the value is within a reasonable range */
    if (sensor_value < 0 || sensor_value > 1) {
        fprintf(stderr, "Invalid sensor data: %d\n", sensor_value);
        return 0;
    }
    return 1;
}

static void publish_sensor_data(MQTTClient client, const char *topic, int sensor_value) {
    char payload[32];
    int rc;

    if (!validate_sensor_data(sensor_value)) {
        fprintf(stderr, "Rejecting invalid sensor data\n");
        return;
    }

    snprintf(payload, sizeof(payload), "%d", sensor_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, topic, &pubmsg, 10000);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message to topic %s: %s\n", topic, MQTTClient_strerror(rc));
    }
}

int main(void) {
    MQTTClient client;
    int rc;
    int sensor_value;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create client, return code %d\n", rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        sensor_value = read_sensor();
        if (sensor_value >= 0) {
            publish_sensor_data(client, MQTT_TOPIC, sensor_value);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
