}

/*
 * HC-SR04 distance measurement on Raspberry Pi using libgpiod.
 *
 * Wiring (BCM numbering):
 *   HC-SR04 TRIG -> GPIO 17 (physical pin 11)
 *   HC-SR04 ECHO -> GPIO 22 (physical pin 15)  [3.3 V safe via divider if using 5 V VCC]
 *   HC-SR04 ECHO -> GPIO 27 (physical pin 13)  [3.3 V safe via divider if using 5 V VCC]
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TRIG_PIN    17
#define ECHO_PIN_1  22
#define ECHO_PIN_2  27

#define SPEED_OF_SOUND_CM_S  34300.0
#define MIN_DISTANCE_CM      2.0
#define MAX_DISTANCE_CM      400.0
#define POLL_INTERVAL_US     100000   /* 0.1 s */
#define ECHO_TIMEOUT_US      300000   /* 300 ms (~5 m round-trip) */
#define TRIG_PULSE_US        10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout / invalid reading.
 */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    struct timespec t_start, t_now;
    long long elapsed_us;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set TRIG low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(2);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Failed to set TRIG high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(TRIG_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set TRIG low: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge (timeout after ECHO_TIMEOUT_US) */
    clock_gettime(CLOCK_MONOTONIC, &t_start);
    while (gpiod_line_get_value(echo) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        elapsed_us = (long long)(t_now.tv_sec - t_start.tv_sec) * 1000000LL
                   + (t_now.tv_nsec - t_start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }

    /* Measure echo pulse width */
    struct timespec echo_start;
    clock_gettime(CLOCK_MONOTONIC, &echo_start);

    while (gpiod_line_get_value(echo) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &t_now);
        elapsed_us = (long long)(t_now.tv_sec - echo_start.tv_sec) * 1000000LL
                   + (t_now.tv_nsec - echo_start.tv_nsec) / 1000LL;
        if (elapsed_us > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &t_now);
    long long pulse_us = (long long)(t_now.tv_sec - echo_start.tv_sec) * 1000000LL
                       + (t_now.tv_nsec - echo_start.tv_nsec) / 1000LL;

    /* distance = (pulse_us * speed_of_sound) / 2 */
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_S / 2000000.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }

    return distance;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo1 = NULL;
    struct gpiod_line *echo2 = NULL;
    int rc = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo1 = gpiod_chip_get_line(chip, ECHO_PIN_1);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN_2);
    if (!trig || !echo1 || !echo2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request all three lines as outputs, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request TRIG line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(echo1, "hcsr04-echo1", 0) < 0) {
        fprintf(stderr, "Failed to request ECHO1 line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(echo2, "hcsr04-echo2", 0) < 0) {
        fprintf(stderr, "Failed to request ECHO2 line: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO %d | ECHO1: GPIO %d | ECHO2: GPIO %d\n",
           TRIG_PIN, ECHO_PIN_1, ECHO_PIN_2);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        float distance = measure_distance(trig, echo1);
        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);
        }
        /* On error, measure_distance already printed a diagnostic */
        usleep(POLL_INTERVAL_US);
    }

    printf("\nExiting...\n");
    rc = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (trig) gpiod_line_release(trig);
    if (echo1) gpiod_line_release(echo1);
    if (echo2) gpiod_line_release(echo2);
    if (chip) gpiod_chip_close(chip);

    return rc;
}

