    printf("GPIO 18 and 24 set HIGH\n");
    fflush(stdout);

    /* Sleep for 5 seconds, checking running flag for early exit */
    for (int i = 0; i < 5 && running; i++) {
        sleep(1);
    }

    /* Set both outputs low before release */
    gpiod_line_set_value(line18, 0);
    gpiod_line_set_value(line24, 0);

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line18) gpiod_line_release(line18);
    if (line24) gpiod_line_release(line24);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
