static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, PIN_1);
    line2 = gpiod_chip_get_line(chip, PIN_2);
    line3 = gpiod_chip_get_line(chip, PIN_3);
    if (!line1 || !line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, "gpio_ctrl", 0) < 0 ||
        gpiod_line_request_output(line2, "gpio_ctrl", 0) < 0 ||
        gpiod_line_request_output(line3, "gpio_ctrl", 0) < 0) {
        perror("gpiod_line_request_output");
