#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "sensor/data"
#define SENSOR_PIN 4
#define POLL_DELAY_US 1000000
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin, int *value) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, pigpio_error(v));
        return -1;
    }
    *value = v;
    return 0;
}

static int validate_sensor_data(int value) {
    return (value == 0 || value == 1);
}

static void publish_sensor_data(MQTTClient *c, const char *topic, int value) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", value);
    int rc = MQTTClient_publishMessage(c, topic, strlen(payload), payload, 0, false);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT publish failed: %s\n", MQTTClient_strerror(rc));
    }
}

static void cleanup(void) {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT,
                               MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTTClient_create failed: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", MQTTClient_strerror(rc));
        cleanup();
        return EXIT_FAILURE;
    }

    while (running) {
        int value;
        if (read_sensor(SENSOR_PIN, &value) != 0) {
            fprintf(stderr, "Sensor read error; retrying in 1 s\n");
            gpioDelay(1000000);
            continue;
        }

        if (!validate_sensor_data(value)) {
            fprintf(stderr, "Invalid sensor data: %d\n", value);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        publish_sensor_data(&client, MQTT_TOPIC, value);
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/reading"
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03
#define ADS1115_REG_ATLAS 0x04
#define ADS1115_REG_CONFIG_OS 0x8000
#define ADS1115_REG_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_REG_CONFIG_PGA_4_096V 0x0200
#define ADS1115_REG_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_REG_CONFIG_DR_128SPS 0x0080
#define ADS1115_REG_CONFIG_CQUE_NONE 0x0003
#define ADS1115_REG_CONFIG_DEFAULT 0xC383
#define ADS1115_REG_CONVERSION_MAX 32767
#define ADS1115_REG_CONVERSION_MIN -32768

static volatile sig_atomic_t running = 1;
static int gpio_initialized = 0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_ads1115_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
    }
    return value;
}

int write_ads1115_register(int handle, uint8_t reg, uint16_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
    }
    return result;
}

int read_ads1115_conversion(int handle) {
    int config = read_ads1115_register(handle, ADS1115_REG_CONFIG);
    if (config < 0) return -1;
    config |= ADS1115_REG_CONFIG_OS;
    if (write_ads1115_register(handle, ADS1115_REG_CONFIG, config) < 0) return -1;

    for (int i = 0; i < 100; i++) {
        int status = read_ads1115_register(handle, ADS1115_REG_CONFIG);
        if (status < 0) return -1;
        if (status & ADS1115_REG_CONFIG_OS) break;
        gpioDelay(1000);
    }

    int raw = read_ads1115_register(handle, ADS1115_REG_CONVERSION);
    if (raw < 0) return -1;
    return (int16_t)raw;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpio_initialized = 1;

    int handle = i2cOpen(1, 0x48, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID_GENERATE, MQTT_CLEAN_SESSION, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < 10 && running; i++) {
        int raw = read_ads1115_conversion(handle);
        if (raw < 0) {
            fprintf(stderr, "Error reading ADS1115, skipping iteration %d\n", i);
            continue;
        }
        float voltage = (raw * 4.096) / ADS1115_REG_CONVERSION_MAX;
        char payload[128];
        snprintf(payload, sizeof(payload), "Sensor %d: %.2f V", i + 1, voltage);

        rc = MQTTClient_publish(client, MQTT_TOPIC, strlen(payload), payload, 0, false);
        if (rc != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish: %s\n", MQTTClient_strerror(rc));
        } else {
            printf("Published: %s\n", payload);
        }
        gpioDelay(1000000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(handle);
    if (gpio_initialized) gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define CONSUMER "gpio-blink"
#define DELAY_US 50000  /* 0.05 s */

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, 17);
    line18 = gpiod_chip_get_line(chip, 18);
    if (!line17 || !line18) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line17, CONSUMER, 0) < 0) {
