        goto cleanup;
    }
    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line18)");
        goto cleanup;
    }

    /* Main loop: toggle each line once, then exit */
    int val17 = 0, val18 = 0;
    while (running) {
        val17 = !val17;
        if (gpiod_line_set_value(line17, val17) < 0) {
            perror("gpiod_line_set_value(line17)");
            goto cleanup;
        }
        printf("GPIO 17 -> %d\n", val17);

        val18 = !val18;
        if (gpiod_line_set_value(line18, val18) < 0) {
            perror("gpiod_line_set_value(line18)");
            goto cleanup;
        }
        printf("GPIO 18 -> %d\n", val18);

        usleep(DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip)   gpiod_chip_close(chip);

