#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int setup_serial_port(int *fd) {
    *fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*fd == -1) {
        perror("open(" SERIAL_PORT ")");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(*fd, &tty) != 0) {
        perror("tcgetattr");
        close(*fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(*fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(*fd);
        return -1;
    }

    return 0;
}

int main(void) {
    int fd = -1;
    char buffer[256];
    size_t buf_len = sizeof(buffer);
    ssize_t bytes_read;

    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_serial_port(&fd) != 0) {
        return EXIT_FAILURE;
    }

    printf("Serial port initialized on %s at 9600 baud.\n", SERIAL_PORT);

    while (running) {
        memset(buffer, 0, buf_len);
        bytes_read = read(fd, buffer, buf_len - 1);

        if (bytes_read > 0) {
            printf("Received: %s\n", buffer);
            fflush(stdout);
        } else if (bytes_read == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("read");
            break;
        }
        usleep(100000);
    }

    if (fd != -1) {
        close(fd);
    }

    printf("\nSerial port closed. Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define SAMPLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 not detected at address 0x%02X.\n", MPU6050_ADDR);
        goto cleanup;
    }

    while (running) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data.\n");
            break;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);
        usleep(SAMPLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR 0x76
#define I2C_DEV "/dev/i2c-1"

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int read_calibration(int fd, bmp280_calib_t *c) {
    uint8_t buf[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, buf, sizeof(buf)) < 0) return -1;
    c->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    c->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    c->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    c->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    c->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    c->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    c->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    c->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    c->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    c->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    c->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    c->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temp(int32_t adc_T, const bmp280_calib_t *c, int32_t *t_fine) {
    int32_t var1 = ((((adc_T >> 3) - ((int32_t)c->dig_T1 << 1))) * ((int32_t)c->dig_T2)) >> 11;
    int32_t var2 = (((((adc_T >> 4) - ((int32_t)c->dig_T1)) * ((adc_T >> 4) - ((int32_t)c->dig_T1))) >> 12) * ((int32_t)c->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_press(int32_t adc_P, const bmp280_calib_t *c, int32_t t_fine) {
    int64_t var1 = ((int64_t)t_fine) - 128000;
    int64_t var2 = var1 * var1 * (int64_t)c->dig_P6;
    var2 = var2 + ((var1 * (int64_t)c->dig_P5) << 17);
    var2 = var2 + (((int64_t)c->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)c->dig_P3) >> 8) + ((var1 * (int64_t)c->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)c->dig_P1) >> 33;
    if (var1 == 0) return 0;
    int64_t p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)c->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)c->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)c->dig_P7) << 4);
    return (uint32_t)p;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave 0x%02X: %s\n", BMP280_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x58). Not a BMP280.\n", id);
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting BMP280: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(2000);

    uint8_t cfg = (0x04 << 5) | (0x02 << 2) | 0x00;
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, cfg) < 0) {
        fprintf(stderr, "Error writing config: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t meas = (0x02 << 5) | (0x05 << 2);
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, meas) < 0) {
        fprintf(stderr, "Error writing ctrl_meas: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        uint8_t data[6];
        if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            break;
        }

        int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
        int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

        int32_t t_fine;
        int32_t temp = compensate_temp(adc_T, &cal, &t_fine);
        uint32_t press = compensate_press(adc_P, &cal, t_fine);

        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp / 100.0, press / 256.0);
        fflush(stdout);

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

