        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM started on GPIO %d, frequency %d Hz, range %d\n",
           PWM_PIN, PWM_FREQ, PWM_RANGE);
    printf("Values applied: 0, 200, 400, 600, 800, 1000\n");

    int values[] = {0, 200, 400, 600, 800, 1000};
    int n = (int)(sizeof(values) / sizeof(values[0]));

    for (int i = 0; i < n && running; i++) {
        if (gpioPWM(PWM_PIN, values[i]) != 0) {
            fprintf(stderr, "PWM write failed for value %d\n", values[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("PWM duty cycle: %d\n", values[i]);
        gpioDelay(200000);
    }

    if (gpioPWM(PWM_PIN, 0) != 0) {
        fprintf(stderr, "Failed to stop PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioTerminate();
    printf("PWM stopped and GPIO released.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_5   5
#define GPIO_6   6
#define GPIO_13  13

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line5 = NULL, *line6 = NULL, *line13 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line5 = gpiod_chip_get_line(chip, GPIO_5);
    line6 = gpiod_chip_get_line(chip, GPIO_6);
    line13 = gpiod_chip_get_line(chip, GPIO_13);
    if (!line5 || !line6 || !line13) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line5, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line6, "gpio_control", 0) < 0 ||
        gpiod_line_request_output(line13, "gpio_control", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("Setting GPIO 5, 6, 13 to LOW\n");
    if (gpiod_line_set_value(line5, 0) < 0 ||
        gpiod_line_set_value(line6, 0) < 0 ||
        gpiod_line_set_value(line13, 0) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    printf("States applied. Exiting.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (line5) gpiod_line_release(line5);
    if (line6) gpiod_line_release(line6);
    if (line13) gpiod_line_release(line13);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/reading"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define SENSOR_PIN 4
#define POLL_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

int main() {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = read_sensor();
        char payload[32];
        snprintf(payload, sizeof(payload), "%d", sensor_value);

        if ((rc = MQTTClient_publish(client, MQTT_TOPIC, strlen(payload), payload, 0, false)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        } else {
            printf("Published: %s\n", payload);
        }

        gpioDelay(POLL_DELAY_US);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PINS {2, 3, 18, 23, 24}
