#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_FRAMES 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

struct buffer {
    void   *start;
    size_t  length;
};

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct buffer *buffers = NULL;
    unsigned int n_buffers = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        goto cleanup;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "Error querying buffer %u: %s\n", n_buffers, strerror(errno));
            goto cleanup;
        }
        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[n_buffers].start == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %u: %s\n", n_buffers, strerror(errno));
            goto cleanup;
        }
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer %u: %s\n", i, strerror(errno));
            goto cleanup;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
            goto cleanup;
        }

        FILE *fp = fopen("image.jpg", "wb");
        if (!fp) {
            fprintf(stderr, "Error opening file: %s\n", strerror(errno));
            goto cleanup;
        }

        size_t written = fwrite(buffers[buf.index].start, 1, buf.bytesused, fp);
        if (written != buf.bytesused) {
            fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            fclose(fp);
            remove("image.jpg");
            goto cleanup;
        }

        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing file: %s\n", strerror(errno));
            remove("image.jpg");
            goto cleanup;
        }

        printf("Captured image: image.jpg (%u bytes)\n", buf.bytesused);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
            goto cleanup;
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        }
    }
    if (buffers) {
        for (unsigned int i = 0; i < n_buffers; ++i) {
            if (buffers[i].start && buffers[i].start != MAP_FAILED) {
                munmap(buffers[i].start, buffers[i].length);
            }
        }
        free(buffers);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
} camera_t;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void cleanup(camera_t *cam) {
    if (cam->buffer && cam->buffer != MAP_FAILED) {
        munmap(cam->buffer, cam->buffer_size);
        cam->buffer = NULL;
    }
    if (cam->fd != -1) {
        close(cam->fd);
        cam->fd = -1;
    }
}

int main(void) {
    camera_t cam;
    CLEAR(cam);

    cam.fd = open("/dev/video0", O_RDWR);
    if (cam.fd < 0) {
        fprintf(stderr, "Error opening /dev/video0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (xioctl(cam.fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: /dev/video0 does not support video capture\n");
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: /dev/video0 does not support streaming I/O\n");
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(cam.fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam.fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(cam.fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    cam.buffer_size = buf.length;
    cam.buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, cam.fd, buf.m.offset);
    if (cam.buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        cam.buffer = NULL;
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (xioctl(cam.fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(cam.fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(cam.fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    int r = select(cam.fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }
    if (r == 0) {
        fprintf(stderr, "Error: capture timed out\n");
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam.fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("image.jpg", "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (fwrite(cam.buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    fclose(fp);

    if (xioctl(cam.fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    cleanup(&cam);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 3
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line1)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(line2)");
        goto cleanup;
    }

    /* Main loop: toggle every 0.5 s until interrupted */
    while (running) {
        int v1 = gpiod_line_get_value(line1);
        int v2 = gpiod_line_get_value(line2);
        if (v1 < 0 || v2 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, v1, GPIO_PIN_2, v2);
        fflush(stdout);

        if (gpiod_line_set_value(line1, v1 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(line1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, v2 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(line2)");
            goto cleanup;
        }

        usleep(500000); /* 0.5 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

