#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (run as root or with appropriate permissions).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialize PWM on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            if (gpioWrite(pins[i], 1) != 0) {
                fprintf(stderr, "Warning: failed to write GPIO %d.\n", pins[i]);
            }
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Warning: failed to set PWM on GPIO %d.\n", pins[i]);
            }
        }
        printf("Pins 17,18,27 -> ON (50%% duty)\n");
        fflush(stdout);
        gpioDelay(500000);

        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
            if (gpioWrite(pins[i], 0) != 0) {
                fprintf(stderr, "Warning: failed to write GPIO %d.\n", pins[i]);
            }
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Warning: failed to set PWM on GPIO %d.\n", pins[i]);
            }
        }
        printf("Pins 17,18,27 -> OFF\n");
        fflush(stdout);
        gpioDelay(500000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_RETRIES 5
#define READ_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms) {
    sleep_us(ms * 1000);
}

static int wait_for_line(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == level) return 0;
        sleep_us(10);
        elapsed += 10;
        if (elapsed >= timeout_us) return -2;
    }
    return -3;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    for (i = 0; i < MAX_RETRIES; i++) {
        memset(data, 0, sizeof(data));

        if (gpiod_line_request_output(line, "dht22", 0) < 0) {
            fprintf(stderr, "Failed to request line as output: %s\n", strerror(errno));
            return -1;
        }
        gpiod_line_set_value(line, 0);
        sleep_ms(2);
        gpiod_line_set_value(line, 1);
        sleep_ms(30);

        if (gpiod_line_request_input(line, "dht22") < 0) {
            fprintf(stderr, "Failed to request line as input: %s\n", strerror(errno));
            return -1;
        }

        int rc = wait_for_line(line, 0, 100);
        if (rc == -3) {
            fprintf(stderr, "Timeout waiting for DHT22 response (no ACK).\n");
            continue;
        }
        if (rc < 0) {
            fprintf(stderr, "GPIO read error during response wait.\n");
            continue;
        }

        rc = wait_for_line(line, 1, 100);
        if (rc == -3) {
            fprintf(stderr, "Timeout waiting for DHT22 data start.\n");
            continue;
        }
        if (rc < 0) {
            fprintf(stderr, "GPIO read error during data start wait.\n");
            continue;
        }

        for (int bit = 0; bit < 40; bit++) {
            rc = wait_for_line(line, 0, 100);
            if (rc == -3) {
                fprintf(stderr, "Timeout waiting for DHT22 bit %d low.\n", bit);
                goto retry;
            }
            if (rc < 0) {
                fprintf(stderr, "GPIO read error during bit %d low wait.\n", bit);
                goto retry;
            }

            sleep_us(40);
            int high = gpiod_line_get_value(line);
            if (high < 0) {
                fprintf(stderr, "GPIO read error during bit %d high wait.\n", bit);
                goto retry;
            }
            if (high == 0) {
                data[bit / 8] |= (1 << (7 - (bit % 8)));
            }

            rc = wait_for_line(line, 1, 100);
            if (rc == -3) {
                fprintf(stderr, "Timeout waiting for DHT22 bit %d high.\n", bit);
                goto retry;
            }
            if (rc < 0) {
                fprintf(stderr, "GPIO read error during bit %d high wait.\n", bit);
                goto retry;
            }
        }

        if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
            fprintf(stderr, "DHT22 checksum error.\n");
            goto retry;
        }

        uint16_t raw_h = (data[0] << 8) | data[1];
        uint16_t raw_t = (data[2] << 8) | data[3];
        *hum = raw_h / 10.0f;
        if (raw_t & 0x8000) {
            *temp = -(raw_t & 0x7FFF) / 10.0f;
        } else {
            *temp = raw_t / 10.0f;
        }

        if (*temp < -40.0f || *temp > 80.0f || *hum < 0.0f || *hum > 100.0f) {
            fprintf(stderr, "DHT22 out-of-range reading: T=%.1fC H=%.1f%%\n", *temp, *hum);
            goto retry;
        }

        printf("DHT22: Temperature = %.1fC, Humidity = %.1f%%\n", *temp, *hum);
        return 0;

    retry:
        sleep_ms(200);
    }
    return -1;
}

