            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u\n", pin_numbers[i]);
                cleanup();
                return EXIT_FAILURE;
            }
            printf("GPIO %u: %s\n", pin_numbers[i], val ? "HIGH" : "LOW");
        }
        printf("---\n");
        fflush(stdout);
        sleep(10);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/mcp3008/reading"
#define MQTT_CLIENT_ID "rpi_mcp3008_publisher"
#define MCP3008_CS_PIN 8
#define MCP3008_CHANNEL 0
#define SAMPLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioWrite(MCP3008_CS_PIN, 0);

    gpioDelay(10);

    int adc_value = gpioRead(MCP3008_CS_PIN);
    gpioWrite(MCP3008_CS_PIN, 1);

    if (adc_value < 0) {
        fprintf(stderr, "Error reading ADC value\n");
        return -1;
    }

    return adc_value;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(MCP3008_CS_PIN, PI_INPUT);

    MQTTClient client;
    int rc = MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        char payload[32];
        snprintf(payload, sizeof(payload), "%d", adc_value);

        rc = MQTTClient_publish(client, MQTT_TOPIC, strlen(payload), payload, 0, false);
        if (rc != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish: %s\n", MQTTClient_strerror(rc));
        } else {
            printf("Published: %s\n", payload);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
} camera_t;

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static void cleanup(camera_t *cam) {
    if (cam->buffer && cam->buffer != MAP_FAILED) {
        munmap(cam->buffer, cam->buffer_size);
    }
    if (cam->fd != -1) {
        close(cam->fd);
    }
}

int main(void) {
    camera_t cam;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned int i;

    cam.fd = -1;
    cam.buffer = MAP_FAILED;
    cam.buffer_size = 0;

    cam.fd = open("/dev/video0", O_RDWR);
    if (cam.fd < 0) {
        fprintf(stderr, "Error opening /dev/video0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(cam.fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(cam.fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam.fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(cam.fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    cam.buffer_size = buf.length;
    cam.buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, cam.fd, buf.m.offset);
    if (cam.buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        cam.buffer = MAP_FAILED;
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (xioctl(cam.fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(cam.fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(cam.fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("image.jpg", "wb");
    if (!fp) {
        fprintf(stderr, "Error opening image.jpg: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    if (fwrite(cam.buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        fprintf(stderr, "Error writing to image.jpg: %s\n", strerror(errno));
        fclose(fp);
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    fclose(fp);

    if (xioctl(cam.fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        cleanup(&cam);
        return EXIT_FAILURE;
    }

    cleanup(&cam);
    return EXIT_SUCCESS;
}

