#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PINS {17, 18, 22, 27}
#define NUM_PINS 4

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    const int pins[NUM_PINS] = PWM_PINS;
    int i;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers\n");
    }

    printf("PWM output started on GPIO %d, %d, %d, %d. Press Ctrl+C to exit.\n",
           pins[0], pins[1], pins[2], pins[3]);
    fflush(stdout);

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Error: PWM write failed on GPIO %d\n", pins[i]);
                running = 0;
                break;
            }
        }
        if (!running) break;
        gpioDelay(100000); /* 100 ms */

        for (i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Error: PWM write failed on GPIO %d\n", pins[i]);
                running = 0;
                break;
            }
        }
        if (!running) break;
        gpioDelay(100000);
    }

    for (i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("\nPWM output stopped. GPIO released.\n");
    return EXIT_SUCCESS;
}

