}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 2
#define GPIO_PIN_2 17
#define SLEEP_DURATION 60

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Register signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 2)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 17)");
        goto cleanup;
    }

    /* Request lines as outputs, initial value low */
    if (gpiod_line_request_output(line1, "rpi-gpio-control", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "rpi-gpio-control", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    printf("Starting GPIO control loop. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle GPIO 2 */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 2 high)");
            break;
        }
        printf("GPIO 2 set HIGH\n");
        fflush(stdout);

        /* Sleep for SLEEP_DURATION seconds, checking keep_running every second */
        for (int i = 0; i < SLEEP_DURATION && keep_running; i++) {
            sleep(1);
        }

        if (!keep_running) {
            break;
        }

        /* Toggle GPIO 17 */
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 17 high)");
            break;
        }
        printf("GPIO 17 set HIGH\n");
        fflush(stdout);

        /* Sleep for SLEEP_DURATION seconds, checking keep_running every second */
        for (int i = 0; i < SLEEP_DURATION && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

#include <stdio.h>
