#include <gpiod.h>

#define NUM_PINS 3
static const unsigned int pin_offsets[NUM_PINS] = {2, 3, 17};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS] = {0, 0, 0};
    int i;
    int ret;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get and request each line as output, initially low */
    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }
        ret = gpiod_line_request_output(lines[i], "rpi-gpio-cycle", 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_offsets[i]);
            goto cleanup;
        }
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Starting 3 cycles of GPIO toggling (Ctrl+C to exit early)\n");

    for (int cycle = 0; cycle < 3 && running; cycle++) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to set GPIO line %u\n", pin_offsets[i]);
                goto cleanup;
            }
            printf("GPIO %u -> %d\n", pin_offsets[i], values[i]);
        }
        printf("---\n");
        fflush(stdout);
        sleep(1);
    }

    printf("Exiting cleanly.\n");

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return (running) ? EXIT_FAILURE : EXIT_SUCCESS;
}

