    fflush(stdout);

    /* Main loop: drive each pin high for 1 second, then low, report state */
    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = 1;
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %u: %s\n",
                        pin_offsets[i], strerror(-ret));
                goto cleanup;
            }
            printf("GPIO %u HIGH\n", pin_offsets[i]);
            fflush(stdout);
        }
        sleep(1);

        for (i = 0; i < NUM_PINS; i++) {
            values[i] = 0;
            ret = gpiod_line_set_value(lines[i], values[i]);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %u: %s\n",
                        pin_offsets[i], strerror(-ret));
                goto cleanup;
            }
            printf("GPIO %u LOW\n", pin_offsets[i]);
            fflush(stdout);
        }
        sleep(4);
    }

cleanup:
    /* Release each line and set it low before releasing */
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

