#define DELAY_US 5000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_pixel_color(int pixel_index, int red, int green, int blue) {
    if (pixel_index < 0 || pixel_index >= NUM_PIXELS) {
        fprintf(stderr, "Invalid pixel index: %d\n", pixel_index);
        return;
    }
    gpioPWM(STRIP_PIN, red);
    gpioDelay(DELAY_US);
    gpioPWM(STRIP_PIN, green);
    gpioDelay(DELAY_US);
    gpioPWM(STRIP_PIN, blue);
    gpioDelay(DELAY_US);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(STRIP_PIN, PI_OUTPUT);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3 && running; i++) {
        set_pixel_color(0, 255, 0, 0);
        set_pixel_color(1, 0, 255, 0);
        set_pixel_color(2, 0, 0, 255);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

