#define GPIO_CHIP "gpiochip0"
#define GPIO_8   8
#define GPIO_17  17

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line8 = NULL, *line17 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line8 = gpiod_chip_get_line(chip, GPIO_8);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line8 || !line17) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line8, "rpi-digital-out", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 8)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line17, "rpi-digital-out", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    /* Drive both lines low initially */
    if (gpiod_line_set_value(line8, 0) < 0 || gpiod_line_set_value(line17, 0) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    printf("Digital output control started. GPIO 8 and GPIO 17 set to LOW.\n");
    fflush(stdout);

    /* Main loop: toggle each line in turn, report state */
    while (running) {
        int v8 = gpiod_line_get_value(line8);
        int v17 = gpiod_line_get_value(line17);
        if (v8 < 0 || v17 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        printf("GPIO 8: %d, GPIO 17: %d\n", v8, v17);
        fflush(stdout);

        /* Toggle GPIO 8 */
        if (gpiod_line_set_value(line8, v8 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value (GPIO 8)");
            goto cleanup;
        }

        /* Toggle GPIO 17 */
        if (gpiod_line_set_value(line17, v17 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            goto cleanup;
        }

        /* Small delay to avoid excessive CPU usage */
        struct timespec ts = {0, 100000000}; /* 100 ms */
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line8) gpiod_line_release(line8);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    printf("Digital output control stopped.\n");
    return ret;
}

