#define W1_DIR "/sys/bus/w1/devices"
#define W1_TEMP_FILE "temp"
#define W1_DEV_FILE "w1_slave"
#define READ_INTERVAL 5
#define MAX_DEVICES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *device_id, float *temp_out) {
    char path[512];
    char line[256];
    FILE *fp;
    int ret = -1;

    snprintf(path, sizeof(path), "%s/%s/%s", W1_DIR, device_id, W1_TEMP_FILE);
    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line, "YES")) {
        char *t = strstr(line, "t=");
        if (t) {
            long millideg = strtol(t + 2, NULL, 10);
            *temp_out = millideg / 1000.0f;
            ret = 0;
        } else {
            fprintf(stderr, "Temperature data not found in: %s\n", line);
        }
    } else {
        fprintf(stderr, "Checksum error in: %s\n", line);
    }
    return ret;
}

int main(void) {
    char device_id[64];
    char list_path[512];
    DIR *dir;
    struct dirent *ent;
    int exit_code = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    snprintf(list_path, sizeof(list_path), "%s/", W1_DIR);
    dir = opendir(list_path);
    if (!dir) {
        fprintf(stderr, "Error opening %s: %s\n", list_path, strerror(errno));
        return 1;
    }

    int found = 0;
    while ((ent = readdir(dir)) != NULL) {
        if (strstr(ent->d_name, "28-") == ent->d_name) {
            strncpy(device_id, ent->d_name, sizeof(device_id) - 1);
            device_id[sizeof(device_id) - 1] = '\0';
            found = 1;
            break;
        }
    }
    closedir(dir);

    if (!found) {
        fprintf(stderr, "No DS18B20 device found. Ensure it is connected and powered.\n");
        return 1;
    }

    for (int i = 0; i < MAX_DEVICES && running; i++) {
        float temp;
        if (read_temperature(device_id, &temp) == 0) {
            printf("Reading %d: Temperature = %.2f C\n", i + 1, temp);
        } else {
            fprintf(stderr, "Failed to read temperature from %s\n", device_id);
            exit_code = 1;
            break;
        }
        if (i < MAX_DEVICES - 1 && running) {
            sleep(READ_INTERVAL);
        }
    }

    return exit_code;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 17
#define GPIO_PIN_2 18

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    if (gpiod_line_request_output(line1, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    printf("GPIO 17 and 18 initialized as outputs. Starting loop.\n");
    fflush(stdout);

    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO values (17=%d, 18=%d)\n", val1, val2);
            goto cleanup;
        }

        printf("GPIO 17: %d, GPIO 18: %d\n", val1, val2);
        fflush(stdout);

        sleep(1);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define ECHO_PIN_ALT 24

#define SPEED_OF_SOUND_CM_S 34300.0
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0;
    }

    struct timespec start, end;
    long long start_ns, end_ns, elapsed_ns;

    for (int i = 0; i < 100; i++) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error reading echo: %s\n", strerror(errno));
            return -1.0;
        }
        if (val == 1) break;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &start);

    for (int i = 0; i < 100; i++) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error reading echo: %s\n", strerror(errno));
            return -1.0;
        }
        if (val == 0) break;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
    elapsed_ns = end_ns - start_ns;

    float distance = (float)elapsed_ns / 1000000000.0 * SPEED_OF_SOUND_CM_S / 2.0;
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *echo_alt = gpiod_chip_get_line(chip, ECHO_PIN_ALT);
    if (!trig || !echo || !echo_alt) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_alt, "hc-sr04-echo-alt") < 0) {
        fprintf(stderr, "Failed to request echo alt line: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("HC-SR04 Ultrasonic Distance Sensor (libgpiod)\n");
    printf("Trigger: GPIO %d, Echo: GPIO %d, Echo Alt: GPIO %d\n", TRIGGER_PIN, ECHO_PIN, ECHO_PIN_ALT);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        float distance = measure_distance(trig, echo);
        if (distance < 0) {
            fprintf(stderr, "Measurement failed, retrying...\n");
            usleep(100000);
            continue;
        }
        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Warning: Distance %.2f cm out of range [%.1f, %.1f]\n", distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        }
        printf("Distance: %.2f cm\n", distance);
        usleep(100000);
    }

    printf("\nExiting...\n");
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(echo_alt);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define NUM_CYCLES 10

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "rpi-gpio-cycle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting %d cycles of GPIO toggling on %s line %d...\n",
           NUM_CYCLES, GPIO_CHIP, GPIO_LINE);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value HIGH");
            break;
        }
        printf("Cycle %d: GPIO %d HIGH\n", i + 1, GPIO_LINE);
        fflush(stdout);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value LOW");
            break;
        }
        printf("Cycle %d: GPIO %d LOW\n", i + 1, GPIO_LINE);
        fflush(stdout);

        /* Sleep 1 second between cycles, but wake early on signal */
        for (int s = 0; s < 10 && running; s++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO cycle complete.\n");
    return EXIT_SUCCESS;
}

