#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 3
static const unsigned int pin_numbers[NUM_PINS] = {17, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = -1;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_numbers[i]);
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "rpi-digital-out", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_numbers[i]);
            goto cleanup;
        }
        values[i] = 0;
    }

    printf("GPIO lines initialized: %u, %u, %u\n", pin_numbers[0], pin_numbers[1], pin_numbers[2]);

    /* Main loop: set each line high, wait, set low, report */
    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value high");
                goto cleanup;
            }
            values[i] = 1;
            printf("GPIO %u HIGH\n", pin_numbers[i]);
            fflush(stdout);
            usleep(500000); /* 500 ms */

            if (!running) break;

            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value low");
                goto cleanup;
            }
            values[i] = 0;
            printf("GPIO %u LOW\n", pin_numbers[i]);
            fflush(stdout);
            usleep(500000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually */
