#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        int v1 = gpioRead(PWM_PIN_1);
        int v2 = gpioRead(PWM_PIN_2);
        int v3 = gpioRead(PWM_PIN_3);

        if (v1 < 0 || v2 < 0 || v3 < 0) {
            fprintf(stderr, "Error: GPIO read failed (v1=%d v2=%d v3=%d)\n", v1, v2, v3);
            break;
        }

        printf("State: PWM1=%d PWM2=%d PWM3=%d\n", v1, v2, v3);
        fflush(stdout);

        gpioDelay(100000); /* 0.1 seconds in microseconds */
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

