#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85
#define DHT22_TIMEOUT 255

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void delay_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void delay_us(unsigned int us) {
    struct timespec ts = { 0, (long)us * 1000L };
    nanosleep(&ts, NULL);
}

static void delay_max(unsigned int max_us) {
    struct timespec ts = { 0, (long)max_us * 1000L };
    while (nanosleep(&ts, &ts) == -1) {
        if (!running) break;
    }
}

static int wait_for_level(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (elapsed < timeout_us) {
        if (gpiod_line_get_value(line) == level) return 0;
        delay_us(1);
        elapsed++;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int last_state = 1;
    int counter = 0;
    int j = 0, i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    delay_ms(50);
    gpiod_line_set_value(line, 0);
    delay_ms(20);
    gpiod_line_set_value(line, 1);
    delay_us(40);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, 100) < 0) return -1;
    if (wait_for_level(line, 1, 100) < 0) return -1;

    for (i = 0; i < MAX_TIMINGS; i++) {
        counter = 0;
        if (wait_for_level(line, 0, 100) < 0) return -1;
        counter = 0;
        while (gpiod_line_get_value(line) == 1) {
            counter++;
            delay_us(1);
            if (counter == DHT22_TIMEOUT) return -1;
        }
        if (counter == DHT22_TIMEOUT) return -1;

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (j < 40) return -1;
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 1, temperature, humidity);
        } else {
            printf("Cycle %d: Error reading DHT22\n", i + 1);
        }
        if (i < 2 && running) delay_ms(1000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 3
static const unsigned int pin_offsets[NUM_PINS] = {2, 3, 17};

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = -1;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line and configure as output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "rpi-digital-out", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_offsets[i]);
            goto cleanup;
        }
        values[i] = 0;
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "Failed to set initial value on GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }
    }

    printf("Digital output control started on GPIO 2, 3, 17 (BCM).\n");
    printf("Initial states: GPIO2=%d, GPIO3=%d, GPIO17=%d\n", values[0], values[1], values[2]);
    fflush(stdout);

    /* Main loop: set values, report, sleep briefly, repeat */
    while (running) {
        values[0] = !values[0];
        if (gpiod_line_set_value(lines[0], values[0]) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO2 -> %d\n", values[0]);
        fflush(stdout);

        values[1] = !values[1];
        if (gpiod_line_set_value(lines[1], values[1]) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO3 -> %d\n", values[1]);
        fflush(stdout);

        values[2] = !values[2];
        if (gpiod_line_set_value(lines[2], values[2]) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO17 -> %d\n", values[2]);
        fflush(stdout);

        usleep(500000); /* 0.5 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release each line individually (safe even if request failed) */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

