#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define PIN_17 17
#define PIN_18 18
#define PIN_23 23

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL, *line23 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line17 = gpiod_chip_get_line(chip, PIN_17);
    line18 = gpiod_chip_get_line(chip, PIN_18);
    line23 = gpiod_chip_get_line(chip, PIN_23);
    if (!line17 || !line18 || !line23) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "rpi-control", 0) < 0 ||
        gpiod_line_request_output(line18, "rpi-control", 0) < 0 ||
        gpiod_line_request_output(line23, "rpi-control", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Set states */
    if (gpiod_line_set_value(line17, 1) < 0 ||
        gpiod_line_set_value(line18, 0) < 0 ||
        gpiod_line_set_value(line23, 1) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    printf("GPIO 17: HIGH, GPIO 18: LOW, GPIO 23: HIGH\n");
    fflush(stdout);

    /* Wait for signal */
    while (running) {
        pause();
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (line23) gpiod_line_release(line23);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18

static volatile sig_atomic_t running = 1;

static void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value low */
    if (gpiod_line_request_output(line17, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output(18)");
        goto cleanup;
    }

    /* Main loop: toggle every second */
    while (running) {
        int val17 = gpiod_line_get_value(line17);
        int val18 = gpiod_line_get_value(line18);
        if (val17 < 0 || val18 < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }
        printf("GPIO 17: %d, GPIO 18: %d\n", val17, val18);
        fflush(stdout);

        /* Toggle GPIO 17 */
        if (gpiod_line_set_value(line17, val17 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(17)");
            goto cleanup;
        }

        /* Toggle GPIO 18 */
        if (gpiod_line_set_value(line18, val18 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(18)");
            goto cleanup;
        }

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
