    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 3
static const unsigned int pin_numbers[NUM_PINS] = {17, 18, 23};

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = -1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_numbers[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_numbers[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "rpi-digital-out", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_numbers[i]);
            goto cleanup;
        }
        values[i] = 0;
        if (gpiod_line_set_value(lines[i], values[i]) < 0) {
            fprintf(stderr, "Failed to set initial value on GPIO %u\n", pin_numbers[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Error reading GPIO %u\n", pin_numbers[i]);
                goto cleanup;
            }
            printf("GPIO %u: %d\n", pin_numbers[i], v);
        }
        printf("---\n");
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting 5 PWM cycles, each 60 seconds. Press Ctrl+C to exit early.\n");

    for (int cycle = 1; cycle <= 5 && running; cycle++) {
        printf("Cycle %d/%d: ", cycle, 5);
        fflush(stdout);

        for (int pin = 0; pin < 4; pin++) {
            if (gpioPWM(pins[pin], 128) != 0) {
                fprintf(stderr, "Warning: PWM write failed on GPIO %d\n", pins[pin]);
            }
        }

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
            printf(".");
            fflush(stdout);
        }

        for (int pin = 0; pin < 4; pin++) {
            if (gpioPWM(pins[pin], 0) != 0) {
                fprintf(stderr, "Warning: PWM write failed on GPIO %d\n", pins[pin]);
            }
        }

        if (running) {
            printf("\n");
            fflush(stdout);
        }
    }

    for (int pin = 0; pin < 4; pin++) {
        gpioPWM(pins[pin], 0);
    }
    gpioTerminate();
    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 17
#define GPIO_PIN_2 27
#define CONSUMER "gpio_control"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 17)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 27)");
        goto cleanup;
    }

    printf("GPIO 17 and 27 initialized as outputs. Starting loop.\n");

    /* Main loop */
    while (running) {
        /* Toggle GPIO 17 */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 17 high)");
            goto cleanup;
        }
        printf("GPIO 17 HIGH\n");
        fflush(stdout);

        /* Wait 2 seconds (interruptible) */
        for (int i = 0; i < 2 && running; i++) {
            sleep(1);
        }

        if (!running) {
            break;
        }

        /* Toggle GPIO 17 back to low */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 17 low)");
            goto cleanup;
        }
        printf("GPIO 17 LOW\n");
        fflush(stdout);

        /* Wait 2 seconds (interruptible) */
        for (int i = 0; i < 2 && running; i++) {
            sleep(1);
        }

        if (!running) {
            break;
        }

        /* Toggle GPIO 27 */
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 27 high)");
            goto cleanup;
        }
        printf("GPIO 27 HIGH\n");
        fflush(stdout);

        /* Wait 2 seconds (interruptible) */
        for (int i = 0; i < 2 && running; i++) {
            sleep(1);
        }

        if (!running) {
            break;
        }

        /* Toggle GPIO 27 back to low */
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 27 low)");
            goto cleanup;
        }
        printf("GPIO 27 LOW\n");
        fflush(stdout);

        /* Wait 2 seconds (interruptible) */
        for (int i = 0; i < 2 && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS 6
static const int pins[NUM_PINS] = {17, 18, 22, 23, 24, 25};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", pins[i]);
            }
        }
        printf("PWM applied to all pins\n");
        fflush(stdout);
        gpioDelay(50000);

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Warning: gpioPWM failed on GPIO %d\n", pins[i]);
            }
        }
        printf("PWM removed from all pins\n");
        fflush(stdout);
        gpioDelay(50000);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated cleanly\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
