           pin_numbers[0], pin_numbers[1], pin_numbers[2]);
    fflush(stdout);

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
