        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define CONSUMER "dht22"
#define MAX_TIMINGS 85
#define DHT22_TIMEOUT 255

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void sleep_us(unsigned int us) {
    struct timespec ts = { 0, (long)us * 1000L };
    nanosleep(&ts, NULL);
}

static int wait_for_level(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (elapsed < timeout_us) {
        if (gpiod_line_get_value(line) == level) return 0;
        sleep_us(1);
        elapsed++;
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    uint8_t laststate = 1;
    uint8_t counter = 0;
    uint8_t j = 0, i;

    memset(data, 0, sizeof(data));

    if (gpiod_line_request_output(line, CONSUMER, 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    sleep_ms(50);
    gpiod_line_set_value(line, 0);
    sleep_ms(20);
    gpiod_line_set_value(line, 1);
    sleep_ms(40);

    if (gpiod_line_request_input(line, CONSUMER) < 0) return -1;

    for (i = 0; i < MAX_TIMINGS; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate) {
            counter++;
            sleep_us(1);
            if (counter == DHT22_TIMEOUT) return -1;
        }
        laststate = gpiod_line_get_value(line);

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (j < 40) return -1;

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -1;

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temperature = -*temperature;

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int cycles = 3;
    int rc = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (cycles > 0 && running) {
        printf("Starting DHT22 read cycle...\n");
        int result = read_dht22(line, &temperature, &humidity);

        if (result == 0) {
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "DHT22 read failed or timeout.\n");
            rc = EXIT_FAILURE;
            break;
        }

        cycles--;
        if (cycles > 0) {
            sleep_ms(60000);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS) {
        printf("Exiting cleanly.\n");
    }

    return rc;
}

