#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 4000000
#define SPI_BITS 8
#define SPI_MODE 0

#define MAX31855_READ_BIT 0x80
#define MAX31855_FAULT_BIT 0x01
#define MAX31855_FAULT_OPEN 0x01
#define MAX31855_FAULT_SHORT 0x02
#define MAX31855_FAULT_GND 0x04
#define MAX31855_FAULT_OVERVOLTAGE 0x08
#define MAX31855_FAULT_UNDERVOLTAGE 0x10
#define MAX31855_FAULT_BRIDGE 0x20

#define MAX31855_DATA_OFFSET 1
#define MAX31855_FAULT_OFFSET 0

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        return -1;
    }
    return 0;
}

static int read_max31855(int fd, uint32_t *raw) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    tx[0] = 0x00;
    tx[1] = 0x00;
    tx[2] = 0x00;
    tx[3] = MAX31855_READ_BIT;

    if (spi_transfer(fd, tx, rx, 4) < 0) {
        return -1;
    }

    uint32_t val = ((uint32_t)rx[2] << 24) |
                   ((uint32_t)rx[3] << 16) |
                   ((uint32_t)rx[0] << 8)  |
                   ((uint32_t)rx[1]);

    *raw = val;
    return 0;
}

static void print_fault(uint32_t raw) {
    if (raw & MAX31855_FAULT_BIT) {
        fprintf(stderr, "MAX31855 Fault: ");
        if (raw & MAX31855_FAULT_OPEN) fprintf(stderr, "Open Circuit ");
        if (raw & MAX31855_FAULT_SHORT) fprintf(stderr, "Short to GND ");
        if (raw & MAX31855_FAULT_GND) fprintf(stderr, "GND fault ");
        if (raw & MAX31855_FAULT_OVERVOLTAGE) fprintf(stderr, "Overvoltage ");
        if (raw & MAX31855_FAULT_UNDERVOLTAGE) fprintf(stderr, "Undervoltage ");
        if (raw & MAX31855_FAULT_BRIDGE) fprintf(stderr, "Bridge fault ");
        fprintf(stderr, "\n");
    }
}

static void print_temperature(uint32_t raw) {
    int32_t val = (int32_t)(raw >> MAX31855_DATA_OFFSET);
    if (val & 0x00010000) {
        val |= 0xFFFFF000;
    }
    double temp = val * 0.25;
    printf("Temperature: %.2f C\n", temp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("MAX31855 Thermocouple Reader\n");
    printf("SPI device: %s, Speed: %d Hz, Bits: %d\n", SPI_DEVICE, SPI_SPEED_HZ, SPI_BITS);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        uint32_t raw;
        if (read_max31855(fd, &raw) < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            break;
        }

        if (raw & 0x00000007) {
            print_fault(raw);
            break;
        }

        print_temperature(raw);
        sleep(1);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

