        return -1;
    }

    int32_t raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_hum = (data[6] << 8) | data[7];

    *press = (float)raw_press / 100.0f;
    *temp = (float)raw_temp / 100.0f;
    *hum = (float)raw_hum / 1000.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "Error: BME280 initialization failed.\n");
        close(fd);
        return 1;
    }

    printf("BME280 initialized. Reading 3 measurements...\n");

    for (int i = 0; i < 3 && running; i++) {
        float temp, hum, press;
        if (bme280_read(fd, &temp, &hum, &press) == 0) {
            printf("Measurement %d: Temp = %.2f C, Hum = %.2f %%, Press = %.2f hPa\n",
                   i + 1, temp, hum, press);
        } else {
            fprintf(stderr, "Error: Failed to read measurement %d.\n", i + 1);
        }
        if (i < 2 && running) sleep(5);
    }

    close(fd);
    printf("Program finished.\n");
    return 0;
}

