#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define VEML7700_ADDR 0x10
#define VEML7700_REG_CONF 0x00
#define VEML7700_REG_ALS_WH 0x04
#define VEML7700_REG_ALS_WL 0x05
#define VEML7700_REG_ALS_WL_FI 0x06
#define VEML7700_REG_ALS_WHI 0x07
#define VEML7700_REG_ALS_WHI_FI 0x08
#define VEML7700_REG_ALS_IR 0x0A
#define VEML7700_REG_ALS_IR_FI 0x0B
#define VEML7700_REG_ALS_VIS 0x0C
#define VEML7700_REG_ALS_VIS_FI 0x0D
#define VEML7700_REG_ALS_UV 0x0E
#define VEML7700_REG_ALS_UV_FI 0x0F
#define VEML7700_REG_TEMP 0x11
#define VEML7700_REG_TEMP_FI 0x12
#define VEML7700_REG_IR_WH 0x14
#define VEML7700_REG_IR_WL 0x15
#define VEML7700_REG_IR_WL_FI 0x16
#define VEML7700_REG_IR_WHI 0x17
#define VEML7700_REG_IR_WHI_FI 0x18
#define VEML7700_REG_IR_IR 0x1A
#define VEML7700_REG_IR_IR_FI 0x1B
#define VEML7700_REG_IR_VIS 0x1C
#define VEML7700_REG_IR_VIS_FI 0x1D
#define VEML7700_REG_IR_UV 0x1E
#define VEML7700_REG_IR_UV_FI 0x1F
#define VEML7700_REG_UV_WH 0x20
#define VEML7700_REG_UV_WL 0x21
#define VEML7700_REG_UV_WL_FI 0x22
#define VEML7700_REG_UV_WHI 0x23
#define VEML7700_REG_UV_WHI_FI 0x24
#define VEML7700_REG_UV_IR 0x26
#define VEML7700_REG_UV_IR_FI 0x27
#define VEML7700_REG_UV_VIS 0x28
#define VEML7700_REG_UV_VIS_FI 0x29
#define VEML7700_REG_UV_UV 0x2A
#define VEML7700_REG_UV_UV_FI 0x2B
#define VEML7700_REG_PARAM 0x2C
#define VEML7700_REG_COMMAND 0x2D

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int veml7700_init(int fd) {
    uint8_t conf = 0x00;
    if (i2c_write_reg8(fd, VEML7700_REG_CONF, conf) < 0) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int veml7700_read_word(int fd, uint8_t reg, uint16_t *val) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        goto cleanup;
    }

    if (veml7700_init(fd) < 0) {
        fprintf(stderr, "Error initializing VEML7700\n");
        goto cleanup;
    }

    while (running) {
        uint16_t als_vis, temp;
        if (veml7700_read_word(fd, VEML7700_REG_ALS_VIS, &als_vis) < 0 ||
            veml7700_read_word(fd, VEML7700_REG_TEMP, &temp) < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            usleep(500000);
            continue;
        }
        printf("ALS_VIS: %u, Temperature: %u\n", als_vis, temp);
        fflush(stdout);
        usleep(500000);
    }

    ret = 0;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_INTERVAL_US 100000  /* 0.1 s */
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int init_serial(int *fd)
{
    *fd = open(SERIAL_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (*fd < 0) {
        perror("open(" SERIAL_PORT ")");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(*fd, &tty) != 0) {
        perror("tcgetattr");
        close(*fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(*fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(*fd);
        return -1;
    }

    tcflush(*fd, TCIOFLUSH);
    return 0;
}

static void cleanup_serial(int fd)
{
    if (fd >= 0) {
        tcflush(fd, TCIOFLUSH);
        close(fd);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    int serial_fd = -1;
    if (init_serial(&serial_fd) != 0) {
        fprintf(stderr, "Serial port initialization failed. Is the device connected?\n");
        return EXIT_FAILURE;
    }

    char buffer[256];
    int retry_count = 0;

    while (g_running) {
        ssize_t bytes_read = read(serial_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
            fflush(stdout);
            retry_count = 0;
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                retry_count++;
                if (retry_count > MAX_RETRIES) {
                    fprintf(stderr, "Device not responding after %d retries.\n", MAX_RETRIES);
                    break;
                }
            } else {
                perror("read");
                break;
            }
        }

        usleep(READ_INTERVAL_US);
    }

    cleanup_serial(serial_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define CONSUMER "hcsr04"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value(trigger low)");
            break;
        }
        usleep(2);

        if (gpiod_line_set_value(trigger, 1) < 0) {
            perror("gpiod_line_set_value(trigger high)");
            break;
        }

        long long start = now_us();
        while (gpiod_line_get_value(echo) == 0) {
            if (!running) break;
            if (now_us() - start > 100000) {
                fprintf(stderr, "Timeout waiting for echo high\n");
                break;
            }
        }
        if (!running) break;

        long long echo_start = now_us();

        while (gpiod_line_get_value(echo) == 1) {
            if (!running) break;
            if (now_us() - echo_start > 100000) {
                fprintf(stderr, "Timeout waiting for echo low\n");
                break;
            }
        }
        if (!running) break;

        long long echo_end = now_us();
        long long pulse_us = echo_end - echo_start;

        if (pulse_us <= 0) {
            fprintf(stderr, "Invalid pulse duration: %lld us\n", pulse_us);
            continue;
        }

        float distance_cm = (float)pulse_us / 58.0f;
        printf("Distance: %.2f cm\n", distance_cm);
        fflush(stdout);

        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 8

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown on Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "rpi-digital-out", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int value = 0;
    while (running) {
        value = !value;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("Output set to %d\n", value);
        fflush(stdout);
        usleep(1000); /* 1 ms delay */
    }

    /* Clean up: set line LOW and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATA_FORMAT 0x31

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    // Set data format: full resolution, +/- 200g range
    if (write(fd, (uint8_t[]){ADXL345_DATA_FORMAT, 0x0B}, 2) != 2) {
        perror("write DATA_FORMAT");
        goto cleanup;
    }

    // Enable measurement mode
    if (write(fd, (uint8_t[]){ADXL345_POWER_CTL, 0x08}, 2) != 2) {
        perror("write POWER_CTL");
        goto cleanup;
    }

    // Read 6 bytes of data
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("read data");
        goto cleanup;
    }

    // Combine into 24-bit signed integer
    int16_t x = (int16_t)((data[1] << 8) | data[0]) >> 4;
    int16_t y = (int16_t)((data[3] << 8) | data[2]) >> 4;
    int16_t z = (int16_t)((data[5] << 8) | data[4]) >> 4;

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
    ret = EXIT_SUCCESS;

cleanup:
    // Put device in standby mode before closing
    if (fd >= 0) {
        write(fd, (uint8_t[]){ADXL345_POWER_CTL, 0x00}, 2);
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 8
static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 23, 24, 25, 27};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
        values[i] = 0;
    }

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error reading GPIO %u\n", pins[i]);
                goto cleanup;
            }
        }
        printf("GPIOs: %u=%d, %u=%d, %u=%d, %u=%d, %u=%d, %u=%d, %u=%d, %u=%d\n",
               pins[0], values[0], pins[1], values[1], pins[2], values[2],
               pins[3], values[3], pins[4], values[4], pins[5], values[5],
               pins[6], values[6], pins[7], values[7]);
        fflush(stdout);
        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

