    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as output, initially low */
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pin_offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", pin_offsets[i]);
            goto cleanup;
        }

        if (gpiod_line_request_output(lines[i], "rpi-digital-out", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", pin_offsets[i]);
            goto cleanup;
        }
        values[i] = 0;
    }

    printf("Starting GPIO output loop. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
        }
        printf("Pins: %u=%d, %u=%d, %u=%d\n",
               pin_offsets[0], values[0],
               pin_offsets[1], values[1],
               pin_offsets[2], values[2]);
        fflush(stdout);

        usleep(500000); /* 0.5 seconds */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and chip resources on all exit paths */
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
