}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PERIOD_US 1000000  /* 1 second in microseconds */
#define DUTY_CYCLE_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* pigpio hardware PWM: duty in range 0..255 */
    if (gpioHardwarePWM(PWM_PIN, PERIOD_US, 0) != 0) {
        fprintf(stderr, "Failed to start hardware PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 0;
    while (running) {
        duty = (duty + 1) % DUTY_CYCLE_RANGE;
        if (gpioHardwarePWM(PWM_PIN, PERIOD_US, duty) != 0) {
            fprintf(stderr, "Failed to update PWM duty cycle\n");
            break;
        }
        printf("Duty cycle: %d/%d\n", duty, DUTY_CYCLE_RANGE);
        fflush(stdout);
        usleep(100000);  /* 0.1 s */
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioHardwarePWM(PWM_PIN, PERIOD_US, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define NUM_CYCLES 5

static volatile sig_atomic_t keep_running = 1;

void int_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO 4)");
        goto cleanup;
    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 17)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "gpio_cycle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "gpio_cycle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    /* Set up signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        goto cleanup;
    }

    printf("Starting 5 cycles of GPIO toggling...\n");

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        /* Turn on both outputs */
        if (gpiod_line_set_value(line1, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 4 high)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 17 high)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 4 and GPIO 17 HIGH\n", i + 1);
        fflush(stdout);

        /* Sleep for 1 second, checking keep_running every 100 ms */
        for (int s = 0; s < 10 && keep_running; s++) {
            usleep(100000);
        }

        /* Turn off both outputs */
        if (gpiod_line_set_value(line1, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 4 low)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 17 low)");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 4 and GPIO 17 LOW\n", i + 1);
        fflush(stdout);

        /* Sleep for the remainder of the 1-second cycle, checking keep_running */
        for (int s = 0; s < 9 && keep_running; s++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);

    printf("Exiting.\n");
    return ret;
}

