        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", GPIO_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", GPIO_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(GPIO_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", GPIO_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_PIN_1, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", GPIO_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(GPIO_PIN_2, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", GPIO_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioPWM(GPIO_PIN_1, 500) != 0) {
            fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", GPIO_PIN_1);
            break;
        }
        if (gpioPWM(GPIO_PIN_2, 500) != 0) {
