#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM started on GPIO %d, %d, %d. Press Ctrl+C to exit.\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);
    fflush(stdout);

    while (running) {
        gpioPWM(PWM_PIN_1, 128);
        gpioPWM(PWM_PIN_2, 255);
        gpioPWM(PWM_PIN_3, 0);
        printf("PWM1=%3d, PWM2=%3d, PWM3=%3d\n", 128, 255, 0);
        fflush(stdout);
        gpioDelay(200000);

        gpioPWM(PWM_PIN_1, 0);
        gpioPWM(PWM_PIN_2, 128);
        gpioPWM(PWM_PIN_3, 255);
        printf("PWM1=%3d, PWM2=%3d, PWM3=%3d\n", 0, 128, 255);
        fflush(stdout);
        gpioDelay(200000);

        gpioPWM(PWM_PIN_1, 128);
        gpioPWM(PWM_PIN_2, 0);
        gpioPWM(PWM_PIN_3, 0);
        printf("PWM1=%3d, PWM2=%3d, PWM3=%3d\n", 128, 0, 0);
        fflush(stdout);
        gpioDelay(200000);
    }

    printf("\nShutting down...\n");
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

