#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ECHO_PIN_ALT 18

#define SPEED_OF_SOUND_CM_S 34300.0
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
        return -1.0;
    }

    struct timespec start, end;
    int timeout = 0;
    while (gpiod_line_get_value(echo) == 0) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
            fprintf(stderr, "clock_gettime start failed: %s\n", strerror(errno));
            return -1.0;
        }
        if (++timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1.0;
        }
        usleep(1);
    }

    timeout = 0;
    while (gpiod_line_get_value(echo) == 1) {
        if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
            fprintf(stderr, "clock_gettime end failed: %s\n", strerror(errno));
            return -1.0;
        }
        if (++timeout > 100000) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1.0;
        }
        usleep(1);
    }

    double elapsed_us = (end.tv_sec - start.tv_sec) * 1000000.0 +
                        (end.tv_nsec - start.tv_nsec) / 1000.0;
    double distance = (elapsed_us * SPEED_OF_SOUND_CM_S) / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        return -1.0;
    }
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *echo_alt = gpiod_chip_get_line(chip, ECHO_PIN_ALT);
    if (!trig || !echo || !echo_alt) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_alt, "hc-sr04-echo-alt") < 0) {
        fprintf(stderr, "Failed to request echo alt line: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_line_release(echo_alt);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 Ultrasonic Distance Sensor (libgpiod)\n");
    printf("Trigger: GPIO %d, Echo: GPIO %d, Echo Alt: GPIO %d\n",
           TRIGGER_PIN, ECHO_PIN, ECHO_PIN_ALT);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        double distance = measure_distance(trig, echo);
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Measurement failed\n");
        }
        usleep(100000);
    }

    printf("\nExiting...\n");
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(echo_alt);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 16

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* 50% duty cycle, 1 kHz frequency */
