#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x10
#define TCS34725_RDATA 0x12
#define TCS34725_GDATA 0x14
#define TCS34725_BDATA 0x16

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x01) < 0) return -1;
    return 0;
}

static void cleanup(int fd) {
    if (fd >= 0) {
        i2c_write_reg8(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        cleanup(fd);
        return 1;
    }

    uint8_t part_id;
    if (i2c_read_reg8(fd, 0x12, &part_id) < 0) {
        fprintf(stderr, "TCS34725 not detected at address 0x%02X.\n", TCS34725_ADDRESS);
        cleanup(fd);
        return 1;
    }
    if (part_id != 0x44) {
        fprintf(stderr, "Unexpected part ID 0x%02X (expected 0x44).\n", part_id);
        cleanup(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725.\n");
        cleanup(fd);
        return 1;
    }

    while (running) {
        uint16_t clear, red, green, blue;
        if (i2c_read_reg16(fd, TCS34725_CDATA, &clear) < 0 ||
            i2c_read_reg16(fd, TCS34725_RDATA, &red) < 0 ||
            i2c_read_reg16(fd, TCS34725_GDATA, &green) < 0 ||
            i2c_read_reg16(fd, TCS34725_BDATA, &blue) < 0) {
            fprintf(stderr, "Error reading color data, retrying...\n");
            usleep(500000);
            continue;
        }
        printf("C: %u, R: %u, G: %u, B: %u\n", clear, red, green, blue);
        fflush(stdout);
        usleep(500000);
    }

    printf("\nExiting cleanly.\n");
    cleanup(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
