    }
    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO 23)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 6)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line2, "rpi-gpio-ctrl", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 23)");
        goto cleanup;
    }

    /* Set both pins high */
