    }
    if (gpiod_line_set_value(line2, 1) < 0) {
        perror("gpiod_line_set_value (GPIO 23)");
        goto cleanup;
    }

    printf("GPIO 6 and GPIO 23 set HIGH\n");
    fflush(stdout);

    /* Sleep for 5 seconds, checking running flag for early exit */
    for (int i = 0; i < 5 && running; i++) {
        sleep(1);
